const bankModules = "[{moduleId:`bank-01-riksbanken-1668`,moduleTitle:`01 · Riksbanken 1668 – från de första sedlarna till världens äldsta centralbank`,moduleTitleEn:`01 · The Riksbank 1668 – from the first banknotes to the world’s oldest central bank`,summary:`Stockholms Banco gav ut Europas första sedlar 1661. Ur den erfarenheten grundades Riksens Ständers Bank 1668, i dag Sveriges riksbank.`,summaryEn:`Stockholms Banco issued Europe’s first banknotes in 1661. From that experience the Estates’ Bank was founded in 1668 – today Sveriges Riksbank.`,durationMinutes:12,topics:[`Riksbanken`,`Stockholms Banco`,`Sedlar`,`Förtroende`,`Quiz`],topicsEn:[`Riksbank`,`Stockholms Banco`,`Banknotes`,`Trust`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur Stockholms Banco gav ut Europas första sedlar,`,`• förklara hur Riksbanken grundades 1668,`,`• nämna Riksbankens inflationsmål i dag.`,`# Sveriges första bank`,`År 1656 fick Johan Palmstruch privilegier för en växelbank och en lånebank. Tillsammans blev de Stockholms Banco, Sveriges första bank.`,`# Europas första sedlar`,`År 1660 började staten prägla nya mynt med lägre vikt. Många insättare ville då ta ut sina gamla, tyngre mynt, och det blev rusning till banken.`,`År 1661 började Stockholms Banco ge ut kreditivsedlar. De lämnades ut som lån och kunde användas för att köpa varor. Det var de första sedlarna i Europa.`,`Med sedlarna kunde banken låna ut så mycket som den var beredd att ge ut i sedlar.`,`# Från succé till krasch`,`Sedlarna blev populära eftersom de var lättare att hantera än tunga kopparmynt. Banken gav ut allt fler sedlar och de minskade i värde. Allmänheten ville växla in sedlarna mot mynt, banken hade för få mynt i kassan och det slutade med en bankkrasch.`,`Riksrådet beslöt 1664 att lånen skulle betalas tillbaka och sedlarna drogs in.`,`# 1668: Riksens Ständers Bank`,`År 1668 beslutade riksdagen att grunda Riksens Ständers Bank ur Stockholms Banco, med adeln, prästerna och borgarna som huvudmän. Ständerna förbjöd sedlar i den nya banken.`,`Banken fick namnet Sveriges riksbank 1867. År 1904 fick Riksbanken ensamrätt att ge ut sedlar.`,`Riksbanken beskriver sig själv som världens äldsta centralbank.`,`# Riksbanken i dag`,`År 1931 fick Riksbanken, som första centralbank i världen, ett prisstabilitetsmål.`,`I dag är målet att inflationen ska vara 2 procent per år, mätt med KPIF (konsumentprisindex med fast ränta).`,`# Sammanfattning`,`Stockholms Banco visade både hur praktiska sedlar är och hur viktigt förtroende är. Riksbanken växte fram ur den erfarenheten.`],quiz:[{id:`bank1-q1`,prompt:`Vad hette Sveriges första bank?`,promptEn:`What was the name of Sweden's first bank?`,promptUk:`Як називався перший банк Швеції?`,options:[xs(`a`,`Riksens Ständers Bank`,!1,`Riksens Ständers Bank`,`Riksens Ständers Bank`),xs(`b`,`Stockholms Banco`,!0,`Stockholms Banco`,`Stockholms Banco`),xs(`c`,`Sveriges riksbank`,!1,`Sveriges riksbank`,`Sveriges riksbank`),xs(`d`,`Skånska privatbanken`,!1,`Skånska privatbanken`,`Skånska privatbanken`)],explanation:`Johan Palmstruch fick privilegier 1656 för det som blev Stockholms Banco.`,explanationEn:`Johan Palmstruch received privileges in 1656 for what became Stockholms Banco.`,explanationUk:`Юган Пальмструх отримав привілеї 1656 року на те, що стало Stockholms Banco.`},{id:`bank1-q2`,prompt:`Vad var kreditivsedlarna?`,promptEn:`What were the kreditivsedlar?`,promptUk:`Чим були kreditivsedlar?`,options:[xs(`a`,`Riksbankens första mynt`,!1,`The Riksbank's first coins`,`Перші монети Риксбанку`),xs(`b`,`Statsobligationer från 1789`,!1,`Government bonds from 1789`,`Державні облігації 1789 року`),xs(`c`,`Kvitton från guldsmeder i London`,!1,`Receipts from goldsmiths in London`,`Розписки золотарів у Лондоні`),xs(`d`,`Europas första sedlar, utgivna av Stockholms Banco 1661`,!0,`Europe's first banknotes, issued by Stockholms Banco in 1661`,`Перші банкноти Європи, випущені Stockholms Banco 1661 року`)],explanation:`Kreditivsedlarna lämnades ut som lån och användes som betalning.`,explanationEn:`The notes were issued as loans and used as payment.`,explanationUk:`Ці папери видавали як позики і використовували як платіж.`},{id:`bank1-q3`,prompt:`Vilket år beslutade riksdagen att grunda Riksens Ständers Bank?`,promptEn:`In which year did the Riksdag decide to found Riksens Ständers Bank?`,promptUk:`У якому році риксдаг вирішив заснувати Riksens Ständers Bank?`,options:[xs(`a`,`1656`,!1,`1656`,`1656`),xs(`b`,`1694`,!1,`1694`,`1694`),xs(`c`,`1668`,!0,`1668`,`1668`),xs(`d`,`1867`,!1,`1867`,`1867`)],explanation:`Banken grundades 1668 och fick namnet Sveriges riksbank 1867.`,explanationEn:`The bank was founded in 1668 and was named Sveriges riksbank in 1867.`,explanationUk:`Банк засновано 1668 року, а назву Sveriges riksbank він отримав 1867 року.`},{id:`bank1-q4`,prompt:`Vilket mål har Riksbanken för inflationen i dag?`,promptEn:`What inflation target does the Riksbank have today?`,promptUk:`Яку ціль щодо інфляції має Риксбанк сьогодні?`,options:[xs(`a`,`2 procent per år, mätt med KPIF`,!0,`2 percent a year, measured with KPIF`,`2 відсотки на рік, міряні KPIF`),xs(`b`,`0 procent`,!1,`0 percent`,`0 відсотків`),xs(`c`,`5 procent per år`,!1,`5 percent a year`,`5 відсотків на рік`),xs(`d`,`Samma som Federal Reserve`,!1,`The same as the Federal Reserve`,`Та сама, що у Federal Reserve`)],explanation:`Målet är 2 procent per år för KPIF.`,explanationEn:`The target is 2 percent a year for KPIF.`,explanationUk:`Ціль — 2 відсотки на рік для KPIF.`}],relatedLinks:[{to:`/tradingskolan?course=historia&lesson=hist-02-guld-korsfarare`,labelSv:`Marknadens historia: Guld & korsfarare`,labelEn:`Market history: Gold & crusaders`,descriptionSv:`Tidig kredit före bankerna`,descriptionEn:`Early credit before the banks`}]},{moduleId:`bank-02-bank-of-england-1694`,moduleTitle:`02 · Bank of England 1694 – banken som lånade ut till staten`,moduleTitleEn:`02 · Bank of England 1694 – the bank that lent to the state`,summary:`Guldsmeder, ett statslån på 1,2 miljoner pund och en bank som med tiden blev Storbritanniens centralbank.`,summaryEn:`Goldsmiths, a £1.2 million loan to the state and a bank that over time became the UK’s central bank.`,durationMinutes:12,topics:[`Bank of England`,`Guldsmeder`,`Statslån`,`Guldmyntfot`,`Quiz`],topicsEn:[`Bank of England`,`Goldsmiths`,`Government loans`,`Gold standard`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara varför Bank of England grundades 1694,`,`• beskriva guldsmedernas roll i tidig engelsk bankverksamhet,`,`• nämna några viktiga steg fram till dagens självständiga centralbank.`,`# Guldsmederna`,`På 1600-talet sköttes tidig bankverksamhet i England av guldsmeder. De förvarade och lånade ut guld och silver, ofta till räntor på 20–30 procent.`,`Guldsmederna gav ut kvitton på mynt som de förvarade, och kvittona började cirkulera som ett slags pengar.`,`År 1672 stoppade kung Karl II återbetalningen av sina lån från guldsmederna. Många guldsmedsfirmor gick omkull och förtroendet för branschen sjönk.`,`# En ny idé: allmänheten lånar ut till staten`,`Kung Vilhelm III behövde pengar till kriget mot Frankrike. Den skotske köpmannen William Paterson föreslog att allmänheten skulle låna staten 1,2 miljoner pund.`,`Långivarna blev delägare i ett nytt aktiebolag, «The Governor and Company of the Bank of England». Staten betalade 8 procent i ränta.`,`Beloppet samlades in på 11 dagar av 1 268 personer.`,`Banken bildades genom ett kungligt privilegiebrev den 27 juli 1694 och öppnade den 1 augusti 1694 med 17 kontorister och två grindvakter.`,`# Sedlar och guld`,`Bank of Englands första sedlar gick att växla mot guld.`,`År 1797 beordrade premiärminister William Pitt d.y. banken att sluta lösa in sedlar mot guld. Den så kallade restriktionsperioden varade till 1821.`,`Bank Charter Act 1844 gav banken nya befogenheter, reglerade sedelutgivningen och stoppade nya banker från att börja ge ut egna sedlar.`,`# Långivare i sista hand`,`År 1866 ställde diskonthuset Overend Gurney in betalningarna. Debatten efteråt formade Bank of Englands roll som långivare i sista hand (lender of last resort).`,`# Mot dagens centralbank`,`År 1931 lämnade Storbritannien guldmyntfoten. Sedan dess är Bank of Englands pengar fiatpengar.`,`År 1946 förstatligades banken.`,`Sedan maj 1997 sätter Bank of England räntan självständigt för att nå inflationsmålet på 2 procent, som regeringen bestämmer.`,`# Sammanfattning`,`Bank of England började som en bank som lånade ut till staten och blev med tiden Storbritanniens centralbank.`],quiz:[{id:`bank2-q1`,prompt:`Varför grundades Bank of England 1694?`,promptEn:`Why was the Bank of England founded in 1694?`,promptUk:`Чому Банк Англії заснували 1694 року?`,options:[xs(`a`,`För att ge ut mynt till kolonierna`,!1,`To issue coins for the colonies`,`Щоб карбувати монети для колоній`),xs(`b`,`För att ersätta Riksbanken`,!1,`To replace the Riksbank`,`Щоб замінити Риксбанк`),xs(`c`,`För att låna staten pengar till kriget mot Frankrike`,!0,`To lend the state money for the war against France`,`Щоб позичити державі гроші на війну проти Франції`),xs(`d`,`För att driva börsen i London`,!1,`To run the exchange in London`,`Щоб керувати біржею в Лондоні`)],explanation:`Allmänheten lånade staten 1,2 miljoner pund och blev delägare i banken.`,explanationEn:`The public lent the state 1.2 million pounds and became owners of the bank.`,explanationUk:`Громадськість позичила державі 1,2 мільйона фунтів і стала співвласниками банку.`},{id:`bank2-q2`,prompt:`Hur mycket lånade allmänheten ut till staten när banken bildades?`,promptEn:`How much did the public lend the state when the bank was formed?`,promptUk:`Скільки громадськість позичила державі, коли банк створювали?`,options:[xs(`a`,`1,2 miljoner pund`,!0,`1.2 million pounds`,`1,2 мільйона фунтів`),xs(`b`,`12 000 pund`,!1,`12,000 pounds`,`12 000 фунтів`),xs(`c`,`4 miljoner pund`,!1,`4 million pounds`,`4 мільйони фунтів`),xs(`d`,`120 miljoner pund`,!1,`120 million pounds`,`120 мільйонів фунтів`)],explanation:`Beloppet samlades in på 11 dagar.`,explanationEn:`The amount was collected in 11 days.`,explanationUk:`Суму зібрали за 11 днів.`},{id:`bank2-q3`,prompt:`Vad hände med guldsmedernas kvitton?`,promptEn:`What happened to the goldsmiths' receipts?`,promptUk:`Що сталося з розписками золотарів?`,options:[xs(`a`,`De brändes varje år`,!1,`They were burned every year`,`Їх спалювали щороку`),xs(`b`,`De började cirkulera som ett slags pengar`,!0,`They began to circulate as a kind of money`,`Вони почали обертатися як різновид грошей`),xs(`c`,`De blev aktier i Bank of England`,!1,`They became shares in the Bank of England`,`Вони стали акціями Банку Англії`),xs(`d`,`De användes bara inom familjen`,!1,`They were used only inside the family`,`Їх використовували лише в родині`)],explanation:`Kvittona på förvarade mynt började användas som betalning.`,explanationEn:`The receipts for stored coins began to be used as payment.`,explanationUk:`Розписки на збережені монети почали використовувати як платіж.`},{id:`bank2-q4`,prompt:`Sedan när sätter Bank of England räntan självständigt?`,promptEn:`Since when has the Bank of England set the interest rate independently?`,promptUk:`Відколи Банк Англії самостійно встановлює ставку?`,options:[xs(`a`,`1694`,!1,`1694`,`1694`),xs(`b`,`1844`,!1,`1844`,`1844`),xs(`c`,`1946`,!1,`1946`,`1946`),xs(`d`,`1997`,!0,`1997`,`1997`)],explanation:`Självständigheten i penningpolitiken gäller sedan maj 1997.`,explanationEn:`Independence in monetary policy has applied since May 1997.`,explanationUk:`Самостійність у монетарній політиці діє з травня 1997 року.`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-01-riksbanken-1668`,labelSv:`Föregående: Riksbanken 1668`,labelEn:`Previous: The Riksbank 1668`}]},{moduleId:`bank-03-rothschild-1800-talet`,moduleTitle:`03 · Familjen Rothschild och 1800-talets europeiska banker`,moduleTitleEn:`03 · The Rothschild family and 19th-century European banking`,summary:`Mayer Amschel Rothschild och hans fem söner byggde bankhus i fem städer och skötte statslån, guldtransporter och järnvägsfinansiering.`,summaryEn:`Mayer Amschel Rothschild and his five sons built banking houses in five cities and handled government loans, gold shipments and railway finance.`,durationMinutes:14,topics:[`Rothschild`,`Statslån`,`Guld`,`Järnvägar`,`Quiz`],topicsEn:[`Rothschild`,`Government loans`,`Gold`,`Railways`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur familjen Rothschild byggde bankhus i fem europeiska städer,`,`• ge exempel på statslån och uppdrag som familjens banker skötte,`,`• förklara hur familjens verksamhet följde industrialiseringen.`,`# Frankfurt och fem söner`,`Bankhuset grundades av Mayer Amschel Rothschild (1744–1812) från Frankfurt am Main och hans fem söner: Amschel, Salomon, Nathan, Karl och Jakob (James).`,`Mayer Amschel arbetade vid hovet hos lantgreve Vilhelm IX av Hessen-Kassel och gjorde helst affärer med regerande furstehus.`,`Sönerna spred verksamheten över Europa. Amschel stannade i Frankfurt, Nathan etablerade sig i London, Jakob i Paris 1811, och Salomon och Karl öppnade kontor i Wien och Neapel på 1820-talet.`,`# Nathan i London`,`Nathan Mayer Rothschild kom till Storbritannien 1798 och drev först textilhandel i Manchester. År 1809 grundade han N M Rothschild vid New Court i Londons finanskvarter, och 1811 satsade han helt på bankverksamhet.`,`Nathan byggde upp ett stort nätverk av kurirer, handlare, mäklare och bankirer för sin handel med guld.`,`# Guld till Wellingtons armé`,`Hertigen av Wellingtons armé behövde guld- och silvermynt för att betala och försörja soldaterna. I januari 1814 anlitade den brittiska regeringens generalkommissarie J.C. Herries Nathan för att skaffa stora mängder guld.`,`Nathans bröder köpte guld runt om i Europa i små poster, och guldet skeppades till Wellington i södra Frankrike. År 1815 fick Nathan ett liknande uppdrag igen.`,`Efter kriget fick Londonhuset uppdraget att förmedla Storbritanniens subsidier till de allierade.`,`# Statslån och en räddning i guld`,`Mellan 1818 och 1835 gav Nathans Londonhus ut 26 brittiska och utländska statslån.`,`År 1826 tillförde firman snabbt guld till Bank of England.`,`Efter freden 1815 arbetade familjens banker allt mer med statspapper från bland annat Preussen, England, Frankrike och Neapel, med försäkringsaktier och med aktier i industribolag.`,`# Järnvägar och industri`,`Familjen följde industrialiseringen med investeringar i järnvägar, kol, järnbruk och metallindustri.`,`Londonhuset specialiserade sig på utländska lån, guldhandel och finansiering av allmännyttiga bolag, särskilt utländska järnvägar.`,`# Två stora lån på 1870-talet`,`Åren 1871–1872 ledde Alphonse de Rothschild, Jakobs son, det bankkonsortium som placerade Frankrikes två stora «befrielselån» efter kriget mot Preussen.`,`År 1875 lånade N M Rothschild & Sons premiärminister Benjamin Disraeli 4 miljoner pund. Pengarna användes till att köpa Egyptens khediv aktier i Suezkanalbolaget åt den brittiska regeringen. Lånet återbetalades inom fem månader.`,`Underhuset beviljade den 21 februari 1876 anslaget på 4 080 000 pund för Suezaktierna.`,`# Sammanfattning`,`Familjen Rothschild byggde ett nätverk av bankhus i fem städer och skötte under 1800-talet stora statslån, guldtransporter och järnvägsfinansiering.`],quiz:[{id:`bank3-q1`,prompt:`I vilken stad började familjen Rothschilds bankhus?`,promptEn:`In which city did the Rothschild family's banking house begin?`,promptUk:`У якому місті почався банківський дім родини Ротшильдів?`,options:[xs(`a`,`London`,!1,`London`,`Лондон`),xs(`b`,`Paris`,!1,`Paris`,`Париж`),xs(`c`,`Frankfurt am Main`,!0,`Frankfurt am Main`,`Франкфурт-на-Майні`),xs(`d`,`Wien`,!1,`Vienna`,`Відень`)],explanation:`Mayer Amschel Rothschild grundade bankhuset i Frankfurt tillsammans med sina fem söner.`,explanationEn:`Mayer Amschel Rothschild founded the banking house in Frankfurt together with his five sons.`,explanationUk:`Маєр Амшель Ротшильд заснував банківський дім у Франкфурті разом із п'ятьма синами.`},{id:`bank3-q2`,prompt:`Vilket uppdrag fick Nathan Rothschild av den brittiska regeringen i januari 1814?`,promptEn:`What task did the British government give Nathan Rothschild in January 1814?`,promptUk:`Яке завдання британський уряд дав Натану Ротшильду в січні 1814 року?`,options:[xs(`a`,`Att skaffa guld- och silvermynt till Wellingtons armé`,!0,`To obtain gold and silver coin for Wellington's army`,`Дістати золоті й срібні монети для армії Веллінгтона`),xs(`b`,`Att bygga en järnväg`,!1,`To build a railway`,`Збудувати залізницю`),xs(`c`,`Att grunda Bank of England`,!1,`To found the Bank of England`,`Заснувати Банк Англії`),xs(`d`,`Att köpa aktier i Suezkanalen`,!1,`To buy shares in the Suez Canal`,`Купити акції Суецького каналу`)],explanation:`Generalkommissarie Herries anlitade Nathan för att skaffa guld till armén.`,explanationEn:`Commissary-general Herries hired Nathan to obtain gold for the army.`,explanationUk:`Генеральний комісар Герріс найняв Натана, щоб дістати золото для армії.`},{id:`bank3-q3`,prompt:`Hur många statslån gav Nathans Londonhus ut mellan 1818 och 1835?`,promptEn:`How many government loans did Nathan's London house issue between 1818 and 1835?`,promptUk:`Скільки державних позик лондонський дім Натана випустив між 1818 і 1835 роками?`,options:[xs(`a`,`2`,!1,`2`,`2`),xs(`b`,`260`,!1,`260`,`260`),xs(`c`,`6`,!1,`6`,`6`),xs(`d`,`26`,!0,`26`,`26`)],explanation:`Londonhuset gav ut 26 brittiska och utländska statslån.`,explanationEn:`The London house issued 26 British and foreign government loans.`,explanationUk:`Лондонський дім випустив 26 британських і закордонних державних позик.`},{id:`bank3-q4`,prompt:`Vad användes lånet på 4 miljoner pund till 1875?`,promptEn:`What was the loan of 4 million pounds in 1875 used for?`,promptUk:`На що пішла позика в 4 мільйони фунтів 1875 року?`,options:[xs(`a`,`Frankrikes befrielselån`,!1,`France's liberation loans`,`Визвольні позики Франції`),xs(`b`,`Den brittiska regeringens köp av khedivens aktier i Suezkanalbolaget`,!0,`The British government's purchase of the khedive's shares in the Suez Canal company`,`Купівля британським урядом акцій хедива в компанії Суецького каналу`),xs(`c`,`Bygget av New Court`,!1,`The building of New Court`,`Будівництво New Court`),xs(`d`,`Kriget mot Napoleon`,!1,`The war against Napoleon`,`Війна проти Наполеона`)],explanation:`Lånet gick till Disraeli för köpet av Suezaktierna och återbetalades inom fem månader.`,explanationEn:`The loan went to Disraeli for the purchase of the Suez shares and was repaid within five months.`,explanationUk:`Позика пішла Дізраелі на купівлю суецьких акцій і була повернена протягом п'яти місяців.`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-02-bank-of-england-1694`,labelSv:`Föregående: Bank of England 1694`,labelEn:`Previous: Bank of England 1694`}]},{moduleId:`bank-04-rothschild-efter-1800-talet`,moduleTitle:`04 · Rothschildhusen efter 1800-talet – en bankvärld i förändring`,moduleTitleEn:`04 · The Rothschild houses after the 19th century – a changing banking world`,summary:`Aktiebanker och insättningsbanker växte fram. Rothschildhusen i Neapel, Frankfurt, Wien och Paris avvecklades, såldes eller förstatligades, och 1989 öppnade ett nytt kontor i Frankfurt.`,summaryEn:`Joint-stock and deposit banks grew. The Rothschild houses in Naples, Frankfurt, Vienna and Paris were wound up, sold or nationalised, and in 1989 a new office opened in Frankfurt.`,durationMinutes:10,topics:[`Rothschild`,`Aktiebanker`,`Förstatligande`,`Quiz`],topicsEn:[`Rothschild`,`Joint-stock banks`,`Nationalisation`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur nya typer av banker växte fram efter 1850,`,`• nämna vad som hände med husen i Neapel, Frankfurt, Wien och Paris,`,`• förklara hur bankverksamheten återkom till Frankfurt 1989.`,`# Nya konkurrenter`,`Från 1850-talet växte nya aktiebanker och insättningsbanker fram i England, Frankrike och de tyska staterna. Under 1800-talets sista kvartal hade andra bankgrupper i Europa och USA blivit större och rikare än Rothschildgruppen.`,`# Neapel 1863`,`Italiens enande 1860 minskade Neapels betydelse. Huset i Neapel, C M de Rothschild e figli, avvecklades 1863 efter 42 år.`,`# Frankfurt 1901`,`När den siste delägaren, Wilhelm Carl von Rothschild, dog 1901 hade Frankfurt fått mindre betydelse som finanscentrum. Familjen beslöt att likvidera M A Rothschild & Söhne.`,`# Wien 1938`,`Vid Tysklands annektering av Österrike 1938 tvingades familjen lämna Wien. År 1939 ställdes S M von Rothschild under det tyska bankhuset Merck, Finck & Co och såldes sedan till dem.`,`Efter kriget fick familjen viss ersättning och valde att avsluta bankverksamheten i Wien för gott.`,`# Paris 1981–1982`,`År 1967 blev de Rothschild Frères aktiebolaget Banque Rothschild.`,`London och Paris var då de sista kvarvarande husen och gjorde allt fler affärer tillsammans.`,`Åren 1981–1982 var Banque Rothschild en av 39 banker som den franska regeringen förstatligade. Banken fick namnet Compagnie Européenne de Banque.`,`# Tillbaka i Frankfurt 1989`,`År 1989 öppnade London- och Parishusen dotterbolaget Rothschild GmbH i Frankfurt, staden där Mayer Amschel Rothschild en gång startade.`,`# Sammanfattning`,`Under 1900-talet förändrades bankvärlden: aktiebanker, insättningsbanker och statliga beslut formade marknaden, och Rothschildhusen i Neapel, Frankfurt, Wien och Paris avvecklades, såldes eller förstatligades.`],quiz:[{id:`bank4-q1`,prompt:`Vilket av Rothschildhusen avvecklades först?`,promptEn:`Which of the Rothschild houses was wound up first?`,promptUk:`Який із домів Ротшильдів згорнули першим?`,options:[xs(`a`,`London`,!1,`London`,`Лондон`),xs(`b`,`Neapel, 1863`,!0,`Naples, 1863`,`Неаполь, 1863`),xs(`c`,`Paris`,!1,`Paris`,`Париж`),xs(`d`,`Wien`,!1,`Vienna`,`Відень`)],explanation:`Efter Italiens enande avvecklades huset i Neapel 1863.`,explanationEn:`After the unification of Italy the house in Naples was wound up in 1863.`,explanationUk:`Після об'єднання Італії дім у Неаполі згорнули 1863 року.`},{id:`bank4-q2`,prompt:`Varför likviderades Frankfurthuset 1901?`,promptEn:`Why was the Frankfurt house liquidated in 1901?`,promptUk:`Чому франкфуртський дім ліквідували 1901 року?`,options:[xs(`a`,`Den siste delägaren dog och Frankfurt hade fått mindre betydelse som finanscentrum`,!0,`The last partner died and Frankfurt had become less important as a financial centre`,`Останній партнер помер, і Франкфурт втратив значення як фінансовий центр`),xs(`b`,`Huset flyttade till New York`,!1,`The house moved to New York`,`Дім переїхав до Нью-Йорка`),xs(`c`,`Det slogs ihop med Bank of England`,!1,`It was merged with the Bank of England`,`Його злили з Банком Англії`),xs(`d`,`Det köptes av Riksbanken`,!1,`It was bought by the Riksbank`,`Його купив Риксбанк`)],explanation:`Wilhelm Carl von Rothschild dog 1901 och familjen beslöt att likvidera banken.`,explanationEn:`Wilhelm Carl von Rothschild died in 1901 and the family decided to liquidate the bank.`,explanationUk:`Вільгельм Карл фон Ротшильд помер 1901 року, і родина вирішила ліквідувати банк.`},{id:`bank4-q3`,prompt:`Vad hände med Banque Rothschild i Paris 1981–1982?`,promptEn:`What happened to Banque Rothschild in Paris in 1981–1982?`,promptUk:`Що сталося з Banque Rothschild у Парижі 1981–1982 років?`,options:[xs(`a`,`Banken flyttade till London`,!1,`The bank moved to London`,`Банк переїхав до Лондона`),xs(`b`,`Banken blev centralbank`,!1,`The bank became a central bank`,`Банк став центральним`),xs(`c`,`Banken förstatligades av den franska regeringen`,!0,`The bank was nationalised by the French government`,`Банк націоналізував французький уряд`),xs(`d`,`Banken börsnoterades i USA`,!1,`The bank was listed in the United States`,`Банк вийшов на біржу в США`)],explanation:`Banque Rothschild var en av 39 banker som förstatligades.`,explanationEn:`Banque Rothschild was one of 39 banks that were nationalised.`,explanationUk:`Banque Rothschild був одним із 39 банків, які націоналізували.`},{id:`bank4-q4`,prompt:`Vilka typer av banker växte fram från 1850-talet?`,promptEn:`What kinds of banks grew from the 1850s?`,promptUk:`Які типи банків зросли з 1850-х?`,options:[xs(`a`,`Tempelbanker`,!1,`Templar banks`,`Банки тамплієрів`),xs(`b`,`Kryptobanker`,!1,`Crypto banks`,`Криптобанки`),xs(`c`,`Centralbanker i varje stad`,!1,`A central bank in every city`,`Центральний банк у кожному місті`),xs(`d`,`Aktiebanker och insättningsbanker`,!0,`Joint-stock banks and deposit banks`,`Акціонерні банки і депозитні банки`)],explanation:`Britannica beskriver hur nya aktiebanker och insättningsbanker växte i England, Frankrike och de tyska staterna.`,explanationEn:`Britannica describes how new joint-stock banks and deposit banks grew in England, France and the German states.`,explanationUk:`Britannica описує, як нові акціонерні банки і депозитні банки зростали в Англії, Франції та німецьких державах.`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-03-rothschild-1800-talet`,labelSv:`Föregående: Rothschild på 1800-talet`,labelEn:`Previous: Rothschild in the 19th century`}]},{moduleId:`bank-05-delreservsystemet`,moduleTitle:`05 · Delreservsystemet – hur bankpengar skapas`,moduleTitleEn:`05 · Fractional reserve banking – how bank money is created`,summary:`Så skapar banker pengar när de lånar ut, vad reservkrav och kapitalkrav är, och hur insättningsgarantin skyddar sparare.`,summaryEn:`How banks create money when they lend, what reserve and capital requirements are, and how deposit insurance protects savers.`,durationMinutes:14,topics:[`Delreserv`,`Bankpengar`,`Kapitalkrav`,`Likviditet`,`Quiz`],topicsEn:[`Fractional reserve`,`Bank money`,`Capital requirements`,`Liquidity`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad ett reservkrav och ett delreservsystem är,`,`• beskriva hur banker skapar pengar när de lånar ut,`,`• nämna vad som begränsar bankernas utlåning i dag.`,`# Grundidén`,`I ett delreservsystem (fractional reserve banking) håller bankerna reserver som motsvarar en andel av insättningarna. Ett reservkrav innebär att banker måste hålla reserver som motsvarar en fast andel av sina insättningar.`,`# Rötterna`,`Guldsmedernas kvitton på förvarade mynt började cirkulera som pengar.`,`Stockholms Banco kunde med sina kreditivsedlar låna ut så mycket som banken var beredd att ge ut i sedlar.`,`# Så skapas pengar i dag`,`I dag består de flesta pengar av bankinsättningar. I Storbritannien utgjorde bankinsättningar 97 procent av de breda pengarna när Bank of England skrev om saken 2014.`,`I Sverige utgör kontanter ungefär 1,5 procent av pengarna. Resten finns på bankkonton.`,`När en bank lämnar ett lån skapar den samtidigt en lika stor insättning på låntagarens konto. Det är nya pengar.`,`När lånet betalas tillbaka minskar mängden bankpengar.`,`# Två sorters pengar`,`• **Centralbankspengar:** sedlar, mynt och bankernas pengar på konton i Riksbankens betalningssystem RIX.`,`• **Bankpengar:** pengar på konton i vanliga banker. De är en fordran på banken.`,`# Vad begränsar utlåningen?`,`Enligt Riksbanken begränsas bankernas utlåning av lagar och regler, bland annat krav på likviditet och kapital, och av hur mycket lån allmänheten efterfrågar. Riksbanken påverkar efterfrågan på lån genom styrräntan.`,`Enligt Bank of England beror mängden pengar ytterst på centralbankens penningpolitik: normalt räntan, och ibland köp av tillgångar (kvantitativa lättnader).`,`# Reservkrav i dag`,`• Enligt Bank of England (2014) spelar reservkrav en liten roll i penningpolitiken i de flesta avancerade ekonomier.`,`• I USA sänkte Federal Reserve reservkraven till 0 procent den 26 mars 2020. Före dess gällde 3 procent och 10 procent på transaktionskonton, beroende på belopp.`,`• I euroområdet kräver ECB att kreditinstitut håller minimireserver på konton hos sin nationella centralbank.`,`• I Sverige sattes Riksbankens kassakrav, alltså reservkravet i penningpolitiken, till 0 procent 1994. Där låg det när Riksbanken beskrev saken 2020.`,`• Sedan den 1 januari 2025 kan Riksbanken kräva räntefri inlåning av kreditinstituten. Från den 11 juni 2026 håller banker och andra kreditinstitut med verksamhet i Sverige 0,2944 procent av sin inlåningsbas som räntefri inlåning i Riksbanken, sammanlagt knappt 35 miljarder kronor. Syftet är att stärka Riksbankens förmåga att finansiera sig själv. Riksbanken prövar kravet varje år.`,`# Kapitalregler`,`Efter bankkollapser 1974 bildade centralbankscheferna i G10 Baselkommittén för banktillsyn. Baselkommittén gav ut Basel Capital Accord 1988, och ramverket har sedan utvecklats i Basel II (2004) och Basel III (2017).`,`# Skydd för insättare`,`Staten skyddar insättningar på bankkonton upp till ett visst belopp genom insättningsgarantin.`,`Insättningsgarantin ersätter kapital och ränta upp till 1 150 000 kronor per person och institut. Beloppet gäller sedan den 1 januari 2026.`,`För insättningar som hör ihop med vissa livshändelser, till exempel försäljning av en bostad, kan ersättningen bli upp till 5 miljoner kronor.`,`# Sammanfattning`,`Banker skapar pengar när de lånar ut. Kapitalkrav, likviditetskrav, efterfrågan på lån och centralbankens ränta sätter ramarna.`],quiz:[{id:`bank5-q1`,prompt:`Vad händer enligt Bank of England när en bank lämnar ett lån?`,promptEn:`According to the Bank of England, what happens when a bank makes a loan?`,promptUk:`Згідно з Банком Англії, що відбувається, коли банк видає позику?`,options:[xs(`a`,`Banken skapar samtidigt en lika stor insättning på låntagarens konto`,!0,`The bank at the same time creates an equal deposit in the borrower's account`,`Банк водночас створює такий самий депозит на рахунку позичальника`),xs(`b`,`Banken hämtar pengarna från Riksbanken`,!1,`The bank fetches the money from the Riksbank`,`Банк бере гроші в Риксбанку`),xs(`c`,`Banken trycker nya sedlar`,!1,`The bank prints new notes`,`Банк друкує нові банкноти`),xs(`d`,`Banken säljer guld`,!1,`The bank sells gold`,`Банк продає золото`)],explanation:`Lånet skapar en motsvarande insättning, alltså nya pengar.`,explanationEn:`The loan creates a matching deposit, which is new money.`,explanationUk:`Позика створює відповідний депозит, тобто нові гроші.`},{id:`bank5-q2`,prompt:`Hur stor del av pengarna i Sverige är kontanter enligt Riksbanken?`,promptEn:`What share of the money in Sweden is cash, according to the Riksbank?`,promptUk:`Яка частка грошей у Швеції — готівка, згідно з Риксбанком?`,options:[xs(`a`,`Ungefär hälften`,!1,`About half`,`Близько половини`),xs(`b`,`Ungefär 25 procent`,!1,`About 25 percent`,`Близько 25 відсотків`),xs(`c`,`Ungefär 1,5 procent`,!0,`About 1.5 percent`,`Близько 1,5 відсотка`),xs(`d`,`Ungefär 97 procent`,!1,`About 97 percent`,`Близько 97 відсотків`)],explanation:`Den allra största delen av pengarna finns på bankkonton.`,explanationEn:`By far the largest part of the money is in bank accounts.`,explanationUk:`Найбільша частина грошей лежить на банківських рахунках.`},{id:`bank5-q3`,prompt:`Vad begränsar bankernas utlåning enligt Riksbanken?`,promptEn:`What limits the banks' lending, according to the Riksbank?`,promptUk:`Що обмежує кредитування банків, згідно з Риксбанком?`,options:[xs(`a`,`Bara mängden guld i valven`,!1,`Only the amount of gold in the vaults`,`Лише кількість золота в сховищах`),xs(`b`,`Krav på kapital och likviditet, efterfrågan på lån och styrräntans påverkan`,!0,`Capital and liquidity requirements, demand for loans, and the effect of the policy rate`,`Вимоги до капіталу і ліквідності, попит на позики і вплив облікової ставки`),xs(`c`,`Antalet bankkontor`,!1,`The number of bank branches`,`Кількість відділень`),xs(`d`,`Vädret`,!1,`The weather`,`Погода`)],explanation:`Regler, efterfrågan och styrräntan sätter ramarna.`,explanationEn:`Rules, demand and the policy rate set the frame.`,explanationUk:`Правила, попит і облікова ставка задають рамку.`},{id:`bank5-q4`,prompt:`Vilket reservkrav har Federal Reserve haft sedan den 26 mars 2020?`,promptEn:`What reserve requirement has the Federal Reserve had since 26 March 2020?`,promptUk:`Яку резервну вимогу Federal Reserve має з 26 березня 2020 року?`,options:[xs(`a`,`10 procent`,!1,`10 percent`,`10 відсотків`),xs(`b`,`3 procent`,!1,`3 percent`,`3 відсотки`),xs(`c`,`20 procent`,!1,`20 percent`,`20 відсотків`),xs(`d`,`0 procent`,!0,`0 percent`,`0 відсотків`)],explanation:`Fed sänkte reservkraven till noll procent för alla inlåningsinstitut.`,explanationEn:`The Fed cut reserve requirements to zero percent for all depository institutions.`,explanationUk:`Fed знизив резервні вимоги до нуля відсотків для всіх депозитних установ.`},{id:`bank5-q5`,prompt:`Vad är bankpengar?`,promptEn:`What is bank money?`,promptUk:`Що таке банківські гроші?`,options:[xs(`a`,`Sedlar från Riksbanken`,!1,`Notes from the Riksbank`,`Банкноти Риксбанку`),xs(`b`,`En fordran på den bank där pengarna finns`,!0,`A claim on the bank where the money sits`,`Вимога до банку, де лежать гроші`),xs(`c`,`Guldmynt`,!1,`Gold coins`,`Золоті монети`),xs(`d`,`Aktier i banken`,!1,`Shares in the bank`,`Акції банку`)],explanation:`Pengar på ett bankkonto är en fordran på banken.`,explanationEn:`Money in a bank account is a claim on the bank.`,explanationUk:`Гроші на банківському рахунку — це вимога до банку.`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-04-rothschild-efter-1800-talet`,labelSv:`Föregående: Rothschildhusen efter 1800-talet`,labelEn:`Previous: The Rothschild houses after 1900`}]},{moduleId:`bank-06-federal-reserve-1913`,moduleTitle:`06 · Federal Reserve 1913 – USA:s centralbank`,moduleTitleEn:`06 · Federal Reserve 1913 – the central bank of the United States`,summary:`Krisen 1907, Aldrich–Vreeland Act och Federal Reserve Act 1913 – och hur Federal Reserve är uppbyggt i dag.`,summaryEn:`The Panic of 1907, the Aldrich–Vreeland Act and the Federal Reserve Act of 1913 – and how the Federal Reserve is organised today.`,durationMinutes:12,topics:[`Federal Reserve`,`Panik 1907`,`Regionala banker`,`FOMC`,`Quiz`],topicsEn:[`Federal Reserve`,`Panic of 1907`,`Regional banks`,`FOMC`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva vilken kris som ledde fram till Federal Reserve,`,`• förklara hur systemet med regionala banker och en central styrelse växte fram,`,`• nämna Federal Reserves mål och uppbyggnad i dag.`,`# Krisen 1907`,`År 1907 sköttes nödlån av privata banker och clearinghus.`,`Den privata sammanslutningen New York Clearing House gav sina medlemsbanker lån i form av clearinghuscertifikat. Certifikaten var föregångare till Federal Reserves diskontlån.`,`Finansmannen J.P. Morgan organiserade privata investeringar och krediter för att stabilisera banksystemet. Han samlade in kontanter från stora finans- och industriföretag till mäklarna på börsen i New York, som därmed kunde hålla öppet.`,`Kongressen ville därefter ha en lösning som byggde på institutioner i stället för på enskilda förmögna personer.`,`# Utredningen`,`Den 30 maj 1908 antog kongressen Aldrich–Vreeland Act. Lagen gav möjlighet till nödvaluta och skapade National Monetary Commission med 18 ledamöter, ledd av senator Nelson Aldrich.`,`Kommissionen reste till Europas huvudstäder och höll utfrågningar i USA. I januari 1911 presenterade Aldrich en plan för en National Reserve Association.`,`# Lagen tar form`,`Efter valet 1912 kontrollerade demokraterna både Vita huset och kongressen.`,`Kongressledamoten Carter Glass ledde arbetet i representanthuset, med hjälp av professor Henry Parker Willis. Glass förslag byggde på regionala banker.`,`President Woodrow Wilson ville ha en central tillsynsmyndighet, och en Federal Reserve Board lades till.`,`Senator Robert L. Owen föreslog högst tolv Reserve Banks. Den slutliga lagen angav mellan åtta och tolv Reserve Banks och tioåriga, förskjutna mandat för styrelsens ledamöter.`,`President Wilson undertecknade Federal Reserve Act den 23 december 1913.`,`# Federal Reserve i dag`,`• **Board of Governors** i Washington D.C.: 7 ledamöter med förskjutna mandat på 14 år, nominerade av presidenten och godkända av senaten.`,`• **12 Federal Reserve Banks** med 24 filialer runt om i landet.`,`• **FOMC** (Federal Open Market Committee): 12 röstande ledamöter som beslutar om penningpolitiken vid minst åtta möten per år.`,`• **Mål från kongressen:** maximal sysselsättning och prisstabilitet.`,`# Sammanfattning`,`Krisen 1907 ledde till fem års utredning och debatt. Resultatet blev 1913 ett system med regionala banker och en central styrelse.`],quiz:[{id:`bank6-q1`,prompt:`Vilken kris ledde fram till arbetet med en amerikansk centralbank?`,promptEn:`Which crisis led to the work on an American central bank?`,promptUk:`Яка криза привела до роботи над американським центральним банком?`,options:[xs(`a`,`Börskraschen 1929`,!1,`The crash of 1929`,`Крах 1929 року`),xs(`b`,`Krisen 2008`,!1,`The crisis of 2008`,`Криза 2008 року`),xs(`c`,`Finanskrisen 1907`,!0,`The financial crisis of 1907`,`Фінансова криза 1907 року`),xs(`d`,`Söderhavsbubblan 1720`,!1,`The South Sea Bubble of 1720`,`Бульба Південних морів 1720 року`)],explanation:`Efter 1907 antogs Aldrich–Vreeland Act och en kommission tillsattes.`,explanationEn:`After 1907 the Aldrich–Vreeland Act was passed and a commission was set up.`,explanationUk:`Після 1907 року ухвалили закон Олдріча–Вріленда і створили комісію.`},{id:`bank6-q2`,prompt:`När undertecknades Federal Reserve Act?`,promptEn:`When was the Federal Reserve Act signed?`,promptUk:`Коли підписали закон про Federal Reserve?`,options:[xs(`a`,`4 juli 1900`,!1,`4 July 1900`,`4 липня 1900`),xs(`b`,`15 augusti 1971`,!1,`15 August 1971`,`15 серпня 1971`),xs(`c`,`27 juli 1694`,!1,`27 July 1694`,`27 липня 1694`),xs(`d`,`23 december 1913`,!0,`23 December 1913`,`23 грудня 1913`)],explanation:`President Wilson undertecknade lagen den 23 december 1913.`,explanationEn:`President Wilson signed the act on 23 December 1913.`,explanationUk:`Президент Вілсон підписав закон 23 грудня 1913 року.`},{id:`bank6-q3`,prompt:`Hur många regionala Federal Reserve Banks finns i dag?`,promptEn:`How many regional Federal Reserve Banks are there today?`,promptUk:`Скільки регіональних банків Federal Reserve є сьогодні?`,options:[xs(`a`,`5`,!1,`5`,`5`),xs(`b`,`12`,!0,`12`,`12`),xs(`c`,`7`,!1,`7`,`7`),xs(`d`,`50`,!1,`50`,`50`)],explanation:`Systemet har 12 Reserve Banks med 24 filialer.`,explanationEn:`The system has 12 Reserve Banks with 24 branches.`,explanationUk:`Система має 12 резервних банків і 24 філії.`},{id:`bank6-q4`,prompt:`Vilka mål har kongressen gett Federal Reserve?`,promptEn:`What goals has Congress given the Federal Reserve?`,promptUk:`Які цілі Конгрес дав Federal Reserve?`,options:[xs(`a`,`Maximal sysselsättning och prisstabilitet`,!0,`Maximum employment and price stability`,`Максимальна зайнятість і стабільність цін`),xs(`b`,`Högsta möjliga börskurser`,!1,`The highest possible share prices`,`Найвищі можливі ціни акцій`),xs(`c`,`Fast guldpris`,!1,`A fixed gold price`,`Фіксована ціна золота`),xs(`d`,`Fast växelkurs mot pundet`,!1,`A fixed exchange rate against the pound`,`Фіксований курс до фунта`)],explanation:`FOMC arbetar mot maximal sysselsättning och prisstabilitet.`,explanationEn:`The FOMC works toward maximum employment and price stability.`,explanationUk:`FOMC працює на максимальну зайнятість і стабільність цін.`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-05-delreservsystemet`,labelSv:`Föregående: Delreservsystemet`,labelEn:`Previous: Fractional reserve banking`}]},{moduleId:`bank-07-bretton-woods-imf`,moduleTitle:`07 · Bretton Woods 1944 och IMF`,moduleTitleEn:`07 · Bretton Woods 1944 and the IMF`,summary:`44 länder möttes i Bretton Woods 1944. Resultatet blev IMF, det som i dag är Världsbanksgruppen och ett växelkurssystem knutet till dollarn och guldet.`,summaryEn:`44 countries met at Bretton Woods in 1944. The result was the IMF, today’s World Bank Group and an exchange-rate system tied to the dollar and gold.`,durationMinutes:13,topics:[`Bretton Woods`,`IMF`,`Världsbanken`,`Guld`,`Dollar`,`Quiz`],topicsEn:[`Bretton Woods`,`IMF`,`World Bank`,`Gold`,`Dollar`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva vad som beslutades i Bretton Woods 1944,`,`• förklara hur växelkurssystemet med dollar och guld fungerade,`,`• nämna IMF:s uppgifter och hur Sverige blev medlem.`,`# Konferensen`,`I juli 1944 samlades delegater från 44 länder på Mount Washington Hotel i Bretton Woods, New Hampshire, för att skapa ett nytt internationellt valutasystem.`,`Målen var stabila växelkurser, att förhindra konkurrerande devalveringar och att främja ekonomisk tillväxt.`,`Huvudarkitekterna var John Maynard Keynes, rådgivare till det brittiska finansdepartementet, och Harry Dexter White, chefsekonom för internationella frågor i det amerikanska finansdepartementet. Den antagna planen liknade Whites förslag, med vissa eftergifter till Keynes.`,`# Två nya institutioner`,`De 730 delegaterna beslutade att bilda två institutioner:`,`• **Internationella valutafonden (IMF)**, som skulle övervaka växelkurserna och låna ut reservvalutor till länder med underskott i betalningsbalansen.`,`• **Internationella banken för återuppbyggnad och utveckling**, i dag Världsbanksgruppen, som skulle stödja återuppbyggnaden efter kriget och utvecklingen i mindre utvecklade länder.`,`IMF:s stadga trädde i kraft den 27 december 1945.`,`# Dollar och guld`,`Länderna höll sina valutor fasta, men justerbara inom 1 procent, mot dollarn. Dollarn var fast mot guld till 35 dollar per uns.`,`År 1958 blev systemet fullt fungerande, när valutorna blev konvertibla.`,`# Slutet på systemet`,`Med tiden fanns fler dollar utomlands än USA hade guld.`,`Den 15 augusti 1971 stängde president Richard Nixon «guldfönstret». Därmed upphörde möjligheten för utländska regeringar att växla dollar mot guld.`,`Riksbanken beskriver 1973 som året då Bretton Woods-samarbetet upphörde. Samma år gick Sverige med i EG:s valutasamarbete, valutaormen.`,`# Sverige och IMF`,`Sverige blev medlem i IMF den 31 augusti 1951.`,`I dag har IMF 191 medlemsländer.`,`# BIS – centralbankernas bank`,`Banken för internationell betalningsutjämning (BIS) grundades 1930 och är den äldsta internationella finansinstitutionen.`,`Konferensen i Bretton Woods antog en resolution om att avveckla BIS. Europeiska centralbanker verkade för att behålla banken, och 1948 lades resolutionen åt sidan.`,`# Sammanfattning`,`Bretton Woods gav världen IMF, Världsbanken och ett system med fasta men justerbara växelkurser knutna till dollarn och guldet. Systemet fungerade fullt ut från 1958 till början av 1970-talet.`],quiz:[{id:`bank7-q1`,prompt:`Hur många länder deltog i Bretton Woods-konferensen 1944?`,promptEn:`How many countries took part in the Bretton Woods conference in 1944?`,promptUk:`Скільки країн брало участь у конференції Бреттон-Вудс 1944 року?`,options:[xs(`a`,`12`,!1,`12`,`12`),xs(`b`,`191`,!1,`191`,`191`),xs(`c`,`44`,!0,`44`,`44`),xs(`d`,`730`,!1,`730`,`730`)],explanation:`Delegater från 44 länder deltog. 730 var antalet delegater.`,explanationEn:`Delegates from 44 countries took part. 730 was the number of delegates.`,explanationUk:`Брали участь делегати з 44 країн. 730 — це кількість делегатів.`},{id:`bank7-q2`,prompt:`Vilka två institutioner beslutades i Bretton Woods?`,promptEn:`Which two institutions were decided at Bretton Woods?`,promptUk:`Які дві установи вирішили в Бреттон-Вудсі?`,options:[xs(`a`,`IMF och det som i dag är Världsbanksgruppen`,!0,`The IMF and what is today the World Bank Group`,`МВФ і те, що сьогодні є Групою Світового банку`),xs(`b`,`Federal Reserve och Bank of England`,!1,`The Federal Reserve and the Bank of England`,`Federal Reserve і Банк Англії`),xs(`c`,`BIS och ECB`,!1,`The BIS and the ECB`,`BIS і ЄЦБ`),xs(`d`,`Riksbanken och Riksgälden`,!1,`The Riksbank and the Swedish National Debt Office`,`Риксбанк і Шведське боргове управління`)],explanation:`IMF och Internationella banken för återuppbyggnad och utveckling.`,explanationEn:`The IMF and the International Bank for Reconstruction and Development.`,explanationUk:`МВФ і Міжнародний банк реконструкції та розвитку.`},{id:`bank7-q3`,prompt:`Till vilket pris var dollarn knuten till guld?`,promptEn:`At what price was the dollar tied to gold?`,promptUk:`За якою ціною долар був прив'язаний до золота?`,options:[xs(`a`,`20 dollar per uns`,!1,`20 dollars per ounce`,`20 доларів за унцію`),xs(`b`,`100 dollar per uns`,!1,`100 dollars per ounce`,`100 доларів за унцію`),xs(`c`,`1 dollar per gram`,!1,`1 dollar per gram`,`1 долар за грам`),xs(`d`,`35 dollar per uns`,!0,`35 dollars per ounce`,`35 доларів за унцію`)],explanation:`Dollarn var fast mot guld till 35 dollar per uns.`,explanationEn:`The dollar was fixed to gold at 35 dollars per ounce.`,explanationUk:`Долар був фіксований до золота за 35 доларів за унцію.`},{id:`bank7-q4`,prompt:`När stängde president Nixon guldfönstret?`,promptEn:`When did President Nixon close the gold window?`,promptUk:`Коли президент Ніксон закрив золоте вікно?`,options:[xs(`a`,`1944`,!1,`1944`,`1944`),xs(`b`,`1958`,!1,`1958`,`1958`),xs(`c`,`1992`,!1,`1992`,`1992`),xs(`d`,`Den 15 augusti 1971`,!0,`15 August 1971`,`15 серпня 1971`)],explanation:`Beslutet i augusti 1971 inledde slutet på Bretton Woods-systemet.`,explanationEn:`The decision in August 1971 began the end of the Bretton Woods system.`,explanationUk:`Рішення в серпні 1971 року почало кінець системи Бреттон-Вудс.`},{id:`bank7-q5`,prompt:`När blev Sverige medlem i IMF?`,promptEn:`When did Sweden become a member of the IMF?`,promptUk:`Коли Швеція стала членом МВФ?`,options:[xs(`a`,`1945`,!1,`1945`,`1945`),xs(`b`,`1973`,!1,`1973`,`1973`),xs(`c`,`1951`,!0,`1951`,`1951`),xs(`d`,`1995`,!1,`1995`,`1995`)],explanation:`Sveriges medlemskap gäller från den 31 augusti 1951.`,explanationEn:`Sweden's membership applies from 31 August 1951.`,explanationUk:`Членство Швеції діє з 31 серпня 1951 року.`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-06-federal-reserve-1913`,labelSv:`Föregående: Federal Reserve 1913`,labelEn:`Previous: Federal Reserve 1913`}]},{moduleId:`bank-08-sa-hanger-det-ihop`,moduleTitle:`08 · Så hänger det ihop i dag`,moduleTitleEn:`08 · How it all connects today`,summary:`Tidslinje, dagens centralbanker, BIS, Baselkommittén och IMF – och Bankkartan med en jämförelse av dagens banker.`,summaryEn:`Timeline, today’s central banks, the BIS, the Basel Committee and the IMF – plus the Bank map comparing today’s banks.`,durationMinutes:12,topics:[`Centralbanker`,`Inflationsmål`,`BIS`,`IMF`,`Bankkartan`,`Quiz`],topicsEn:[`Central banks`,`Inflation targets`,`BIS`,`IMF`,`Bank map`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur centralbankerna arbetar i dag,`,`• förklara hur centralbanker, affärsbanker, BIS och IMF hänger ihop,`,`• hitta en uppdaterad jämförelse av dagens banker i Bankkartan.`,`# Tidslinje`,`• 1661 – Stockholms Banco ger ut Europas första sedlar`,`• 1668 – Riksens Ständers Bank, i dag Riksbanken, grundas`,`• 1694 – Bank of England grundas`,`• 1814–1815 – Nathan Rothschild skaffar guld till Wellingtons armé`,`• 1844 – Bank Charter Act i Storbritannien`,`• 1875 – Rothschildlånet för Suezaktierna`,`• 1913 – Federal Reserve Act`,`• 1930 – BIS grundas`,`• 1944 – Bretton Woods-konferensen`,`• 1971 – Guldfönstret stängs`,`• 1974 – Baselkommittén bildas`,`• 1997 – Bank of England får självständighet i penningpolitiken`,`• 2020 – Federal Reserve sänker reservkraven till 0 procent`,`# Centralbankerna i dag`,`• **Riksbanken** har inflationsmålet 2 procent per år mätt med KPIF. En ny riksbankslag gäller sedan den 1 januari 2023.`,`• **Bank of England** sätter räntan självständigt för att nå inflationsmålet på 2 procent, som regeringen bestämmer.`,`• **Federal Reserve** arbetar mot maximal sysselsättning och prisstabilitet.`,`# Affärsbankerna`,`Affärsbankerna skapar största delen av pengarna när de lånar ut. Kapitalkrav, likviditetskrav, efterfrågan på lån och centralbankens ränta sätter ramarna.`,`# Samarbetet mellan länder`,`• **BIS** är en bank för centralbanker. Den ägs av 63 centralbanker från länder som tillsammans står för omkring 95 procent av världens BNP.`,`• **Baselkommittén** tar fram gemensamma kapitalregler för internationellt aktiva banker, i dag Basel III.`,`• **IMF** har 191 medlemmar. IMF följer medlemsländernas ekonomi genom återkommande granskningar, lånar ut till länder med betalningsbalansproblem och ger teknisk rådgivning till myndigheter. Enligt årsrapporten 2026 lånade IMF ut totalt 40 miljarder dollar till 18 länder.`,`# Den röda tråden`,`Riksbanken och Bank of England började som banker med nära band till staten. I dag har de tydliga uppdrag, egna mål och självständighet i penningpolitiken.`,`Rothschildhusen visar hur privata bankhus skötte stora statslån på 1800-talet. Från 1850-talet växte aktiebanker och insättningsbanker fram som nya aktörer.`,`Bretton Woods lade grunden för det internationella samarbete som IMF, Världsbanken och BIS står för i dag.`,`# Så ser det ut i dag – Bankkartan`,`Vill du se hur dagens banker står sig på avgifter, uttag och regler? Bankkartan under Kapital & Strategi samlar en jämförelse med datum för senaste uppdatering.`,`Bankkartan öppnar du under «Video & verktyg» längst ned i lektionen: https://www.kapitalstrategi.com/kapital-och-strategi?tab=bankkarta`,`Bankkartan är en pedagogisk jämförelse. Kontrollera alltid villkor hos banken själv.`,`Historien slutar inte här. Hur banker och betalningar fungerar i dag kan du lära dig vidare genom det våra kunder rapporterar till oss och genom det vi har kunnat identifiera på internet.`,`Det vi delar är sammanställt och avidentifierat, och det är iakttagelser, inte en garanti för hur en viss bank agerar.`],contentEn:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur centralbankerna arbetar i dag,`,`• förklara hur centralbanker, affärsbanker, BIS och IMF hänger ihop,`,`• hitta en uppdaterad jämförelse av dagens banker i Bankkartan.`,`# Tidslinje`,`• 1661 – Stockholms Banco ger ut Europas första sedlar`,`• 1668 – Riksens Ständers Bank, i dag Riksbanken, grundas`,`• 1694 – Bank of England grundas`,`• 1814–1815 – Nathan Rothschild skaffar guld till Wellingtons armé`,`• 1844 – Bank Charter Act i Storbritannien`,`• 1875 – Rothschildlånet för Suezaktierna`,`• 1913 – Federal Reserve Act`,`• 1930 – BIS grundas`,`• 1944 – Bretton Woods-konferensen`,`• 1971 – Guldfönstret stängs`,`• 1974 – Baselkommittén bildas`,`• 1997 – Bank of England får självständighet i penningpolitiken`,`• 2020 – Federal Reserve sänker reservkraven till 0 procent`,`# Centralbankerna i dag`,`• **Riksbanken** har inflationsmålet 2 procent per år mätt med KPIF. En ny riksbankslag gäller sedan den 1 januari 2023.`,`• **Bank of England** sätter räntan självständigt för att nå inflationsmålet på 2 procent, som regeringen bestämmer.`,`• **Federal Reserve** arbetar mot maximal sysselsättning och prisstabilitet.`,`# Affärsbankerna`,`Affärsbankerna skapar största delen av pengarna när de lånar ut. Kapitalkrav, likviditetskrav, efterfrågan på lån och centralbankens ränta sätter ramarna.`,`# Samarbetet mellan länder`,`• **BIS** är en bank för centralbanker. Den ägs av 63 centralbanker från länder som tillsammans står för omkring 95 procent av världens BNP.`,`• **Baselkommittén** tar fram gemensamma kapitalregler för internationellt aktiva banker, i dag Basel III.`,`• **IMF** har 191 medlemmar. IMF följer medlemsländernas ekonomi genom återkommande granskningar, lånar ut till länder med betalningsbalansproblem och ger teknisk rådgivning till myndigheter. Enligt årsrapporten 2026 lånade IMF ut totalt 40 miljarder dollar till 18 länder.`,`# Den röda tråden`,`Riksbanken och Bank of England började som banker med nära band till staten. I dag har de tydliga uppdrag, egna mål och självständighet i penningpolitiken.`,`Rothschildhusen visar hur privata bankhus skötte stora statslån på 1800-talet. Från 1850-talet växte aktiebanker och insättningsbanker fram som nya aktörer.`,`Bretton Woods lade grunden för det internationella samarbete som IMF, Världsbanken och BIS står för i dag.`,`# Så ser det ut i dag – Bankkartan`,`Vill du se hur dagens banker står sig på avgifter, uttag och regler? Bankkartan under Kapital & Strategi samlar en jämförelse med datum för senaste uppdatering.`,`Bankkartan öppnar du under «Video & verktyg» längst ned i lektionen: https://www.kapitalstrategi.com/kapital-och-strategi?tab=bankkarta`,`Bankkartan är en pedagogisk jämförelse. Kontrollera alltid villkor hos banken själv.`,`The story does not end here. You can go on learning how banks and payments work today through what our customers report to us and through what we have been able to identify on the internet.`,`What we share is compiled and anonymised, and these are observations, not a guarantee of how any particular bank acts.`],quiz:[{id:`bank8-q1`,prompt:`Vem bestämmer Bank of Englands inflationsmål?`,promptEn:`Who sets the Bank of England's inflation target?`,promptUk:`Хто встановлює ціль Банку Англії щодо інфляції?`,options:[xs(`a`,`IMF`,!1,`The IMF`,`МВФ`),xs(`b`,`Den brittiska regeringen`,!0,`The British government`,`Британський уряд`),xs(`c`,`Federal Reserve`,!1,`The Federal Reserve`,`Federal Reserve`),xs(`d`,`Bankernas styrelser`,!1,`The banks' boards`,`Правління банків`)],explanation:`Regeringen sätter målet på 2 procent. Bank of England sätter räntan för att nå det.`,explanationEn:`The government sets the target of 2 percent. The Bank of England sets the rate to reach it.`,explanationUk:`Уряд ставить ціль у 2 відсотки. Банк Англії встановлює ставку, щоб її досягти.`},{id:`bank8-q2`,prompt:`Vad är BIS?`,promptEn:`What is the BIS?`,promptUk:`Що таке BIS?`,options:[xs(`a`,`En bank för centralbanker, ägd av 63 centralbanker`,!0,`A bank for central banks, owned by 63 central banks`,`Банк для центральних банків, у власності 63 центральних банків`),xs(`b`,`En vanlig sparbank`,!1,`An ordinary savings bank`,`Звичайний ощадний банк`),xs(`c`,`En del av Riksbanken`,!1,`A part of the Riksbank`,`Частина Риксбанку`),xs(`d`,`En börs i Basel`,!1,`An exchange in Basel`,`Біржа в Базелі`)],explanation:`BIS tjänar centralbanker och främjar samarbete mellan dem.`,explanationEn:`The BIS serves central banks and promotes cooperation among them.`,explanationUk:`BIS служить центральним банкам і сприяє співпраці між ними.`},{id:`bank8-q3`,prompt:`Hur många medlemsländer har IMF i dag?`,promptEn:`How many member countries does the IMF have today?`,promptUk:`Скільки країн-членів має МВФ сьогодні?`,options:[xs(`a`,`44`,!1,`44`,`44`),xs(`b`,`63`,!1,`63`,`63`),xs(`c`,`29`,!1,`29`,`29`),xs(`d`,`191`,!0,`191`,`191`)],explanation:`IMF har 191 medlemmar.`,explanationEn:`The IMF has 191 members.`,explanationUk:`МВФ має 191 члена.`},{id:`bank8-q4`,prompt:`Vilka skapar största delen av pengarna i dag?`,promptEn:`Who creates most of the money today?`,promptUk:`Хто створює більшу частину грошей сьогодні?`,options:[xs(`a`,`IMF`,!1,`The IMF`,`МВФ`),xs(`b`,`Guldgruvor`,!1,`Gold mines`,`Золоті копальні`),xs(`c`,`Affärsbankerna, när de lånar ut`,!0,`The commercial banks, when they lend`,`Комерційні банки, коли видають позики`),xs(`d`,`BIS`,!1,`The BIS`,`BIS`)],explanation:`Bankinsättningar är den största delen av pengarna och skapas främst genom utlåning.`,explanationEn:`Bank deposits are the largest part of the money and are created mainly through lending.`,explanationUk:`Банківські депозити — найбільша частина грошей, і їх створюють переважно через кредитування.`}],relatedLinks:[{to:`/kapital-och-strategi?tab=bankkarta`,labelSv:`Bankkartan`,labelEn:`Bank map`,descriptionSv:`Dagens banker: premier, uttag och regler`,descriptionEn:`Today’s banks: fees, withdrawals and rules`},{to:`/tradingskolan?course=bankernas-historia&lesson=bank-07-bretton-woods-imf`,labelSv:`Föregående: Bretton Woods och IMF`,labelEn:`Previous: Bretton Woods and the IMF`}]}]";
const mfModules = "[{moduleId:`mf-01-fran-bocker-till-ledger`,moduleTitle:`01 · Från böckerna till ledgern – återblick på skepp och korsfarare`,moduleTitleEn:`01 · From books to the ledger – looking back at ships and crusaders`,summary:`Tempelriddarnas konton, VOC:s aktiebok och bankernas böcker – den röda tråden från pappersbok till delad ledger.`,summaryEn:`The Templars’ accounts, the VOC share register and the banks’ books – the common thread from a written book to a shared ledger.`,durationMinutes:14,topics:[`Tempelriddarna`,`VOC`,`Bankböcker`,`Ledger`,`Quiz`],topicsEn:[`Templars`,`VOC`,`Bank books`,`Ledger`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur tempelriddarna och VOC förde böcker över andras pengar och andelar,`,`• förklara vad en ledger är,`,`• följa den röda tråden från pappersböcker till digitala och delade ledgers.`,`# Återblick: skepp och korsfarare`,`I kursen «Marknadens historia» mötte du korsfararna och skeppen. Här tar vi upp tråden igen. Den följer oss genom hela kursen: **ledgern**, boken där någon skriver in vem som äger vad.`,`**Tempelriddarna som bankirer.** Tempelherreorden grundades omkring 1119–1120 för att skydda kristna pilgrimer på väg till Jerusalem. Orden hade hus i många länder i Europa och i det heliga landet.`,`Tack vare sin styrka kunde orden säkert samla in, förvara och transportera ädelmetall mellan Europa och det heliga landet. Nätverket av förråd och den effektiva transporten gjorde orden attraktiv som bankir åt både kungar och pilgrimer.`,`Historikern Léopold Delisle gick 1889 igenom de bevarade handlingarna. Ordens hus tog emot insättningar från kungar, furstar, borgare och köpmän. Parisborgaren Pierre Sarrasin skrev sitt testamente i juni 1220, inför en pilgrimsfärd till Santiago de Compostela. Hans kapital fanns hos Tempelherrarna i Paris, och det som återstod skulle förvaras där tills arvingarna blev myndiga. Den franske kungens skattkammare låg i Tempelherrarnas hus i Paris i mer än hundra år.`,`Orden gjorde också betalningar på andra orter genom brev och bokföringsposter, så att pengarna kunde stå kvar där de låg. Flera kunder hade löpande konton hos orden. År 1235 betalade Henrik III av England in pengar till Tempelherrarnas hus i London, och ordens mästare i England lät betala ut 800 livres tournois vid huset i Paris.`,`**Skeppen och handelskompanierna.** Det holländska Ostindiska kompaniet, VOC, grundades 1602. Samma år köpte Pieter Harmensz en andel på 150 gulden i kompaniets kammare i Enkhuizen. Kvittot på hans sista inbetalning 1606 räknas som världens äldsta bevarade aktie.`,`VOC gav ut kvitton som bevis på betalning. Själva ägandet fanns i kompaniets böcker: bokhållarna förde in varje insats och varje ägarbyte. Utdelningen betalades ut efter aktieägarregistren i VOC:s sex kammare.`,`# Från pappersbok till digital bok`,`I kursen «Bankernas historia» följer du hur bankerna tog över boken. När en bank lånar ut skriver den in ett nytt belopp på låntagarens konto, och bankinsättningar är den största delen av pengarna i dag.`,`Banken för internationella betalningar, BIS, sammanfattar utvecklingen så här: pengar som bokföringsposter hos betrodda mellanhänder gav upphov till nya finansiella instrument, och pappersböckerna ersattes av digitala.`,`# Vad är en ledger?`,`En ledger är en huvudbok över transaktioner och innehav. En blockkedja är en digital ledger som delas mellan många datorer och som gör ändringar synliga och svåra att genomföra.`,`# Den röda tråden i kursen`,`• **Lektion 02:** algoritmer och AI lägger order, och företagen för register över sin handel.`,`• **Lektion 03:** krypto bygger på en ledger som delas mellan deltagarna i ett nätverk.`,`• **Lektion 04:** en CBDC är centralbankspengar i digital form. Den digitala euron är tänkt att föras på en central plattform som Eurosystemet driver.`,`• **Lektion 05:** vid en ICO förs nya tokens in i en ledger.`,`• **Lektion 06:** vid självförvar håller du själv nyckeln till dina poster i ledgern.`,`• **Lektion 07:** BIS beskriver en framtida «unified ledger» där centralbankspengar, bankpengar och tokeniserade tillgångar samlas.`,`# Sammanfattning`,`Tempelherrarnas konton, VOC:s aktiebok och bankernas konton är alla betrodda böcker över andras tillgångar. I dag finns boken också i digital och delad form.`],quiz:[{id:`mf1-q1`,prompt:`Vem anlitade tempelriddarna som bankirer?`,promptEn:`Who used the Knights Templar as bankers?`,promptUk:`Хто користувався тамплієрами як банкірами?`,options:[xs(`a`,`Både kungar och pilgrimer`,!0,`Both kings and pilgrims`,`І королі, і паломники`),xs(`b`,`Bara köpmän i Amsterdam`,!1,`Only merchants in Amsterdam`,`Лише купці в Амстердамі`),xs(`c`,`Bara Riksbanken`,!1,`Only the Riksbank`,`Лише Риксбанк`),xs(`d`,`VOC:s aktieägare`,!1,`The VOC's shareholders`,`Акціонери VOC`)],explanation:`Ordens nätverk av förråd och säkra transporter gjorde den attraktiv som bankir åt kungar och pilgrimer.`,explanationEn:`The order's network of stores and safe transport made it attractive as a banker for kings and pilgrims.`,explanationUk:`Мережа складів ордену і безпечне перевезення робили його привабливим банкіром для королів і паломників.`},{id:`mf1-q2`,prompt:`Hur kunde Tempelherrarna betala ut pengar på en annan ort?`,promptEn:`How could the Templars pay out money in another place?`,promptUk:`Як тамплієри могли виплатити гроші в іншому місці?`,options:[xs(`a`,`Genom att trycka sedlar`,!1,`By printing notes`,`Друкуючи банкноти`),xs(`b`,`Via en börs i Amsterdam`,!1,`Via an exchange in Amsterdam`,`Через біржу в Амстердамі`),xs(`c`,`Genom brev och bokföringsposter mellan ordens hus`,!0,`Through letters and bookkeeping entries between the order's houses`,`Через листи і бухгалтерські записи між домами ордену`),xs(`d`,`Genom en centralbank`,!1,`Through a central bank`,`Через центральний банк`)],explanation:`Delisle beskriver betalningar på avstånd genom korrespondens och bokföring, så att pengarna kunde stå kvar.`,explanationEn:`Delisle describes payments at a distance through correspondence and bookkeeping, so the money could stay where it was.`,explanationUk:`Деліль описує платежі на відстані через листування і облік, тож гроші могли лишатися на місці.`},{id:`mf1-q3`,prompt:`Var fanns ägandet i VOC?`,promptEn:`Where did ownership in the VOC sit?`,promptUk:`Де була власність у VOC?`,options:[xs(`a`,`I aktiebrev som delades ut`,!1,`In share certificates that were handed out`,`У акціонерних свідоцтвах, які роздавали`),xs(`b`,`Hos Riksbanken`,!1,`At the Riksbank`,`У Риксбанку`),xs(`c`,`I en blockkedja`,!1,`On a blockchain`,`У блокчейні`),xs(`d`,`I kompaniets böcker, där varje insats och ägarbyte fördes in`,!0,`In the company's books, where every contribution and change of owner was entered`,`У книгах компанії, куди вносили кожен внесок і кожну зміну власника`)],explanation:`VOC gav ut kvitton, och bokhållarna förde in insatser och ägarbyten i böckerna.`,explanationEn:`The VOC issued receipts, and the bookkeepers entered contributions and changes of owner in the books.`,explanationUk:`VOC видавала розписки, а бухгалтери вносили внески і зміни власника в книги.`},{id:`mf1-q4`,prompt:`Vad är en blockkedja enligt NIST?`,promptEn:`What is a blockchain according to NIST?`,promptUk:`Що таке блокчейн згідно з NIST?`,options:[xs(`a`,`En pappersbok i ett bankvalv`,!1,`A paper book in a bank vault`,`Паперова книга в банківському сховищі`),xs(`b`,`En digital ledger som delas mellan många datorer`,!0,`A digital ledger shared between many computers`,`Цифрова книга, спільна для багатьох комп'ютерів`),xs(`c`,`Ett aktiebrev från VOC`,!1,`A share certificate from the VOC`,`Акціонерне свідоцтво VOC`),xs(`d`,`Ett kreditkort`,!1,`A credit card`,`Кредитна картка`)],explanation:`NIST beskriver blockkedjor som delade digitala ledgers där ändringar syns och är svåra att genomföra.`,explanationEn:`NIST describes blockchains as shared digital ledgers where changes are visible and hard to make.`,explanationUk:`NIST описує блокчейни як спільні цифрові книги, де зміни видно і їх важко зробити.`}],relatedLinks:[{to:`/tradingskolan?course=historia&lesson=hist-01-skepp-till-aktier`,labelSv:`Marknadens historia: Skepp → aktier`,labelEn:`Market history: Ships → shares`,descriptionSv:`VOC och de första aktierna`,descriptionEn:`The VOC and the first shares`},{to:`/tradingskolan?course=historia&lesson=hist-02-guld-korsfarare`,labelSv:`Marknadens historia: Guld & korsfarare`,labelEn:`Market history: Gold & crusaders`,descriptionSv:`Tidig kredit före bankerna`,descriptionEn:`Early credit before the banks`},{to:`/tradingskolan?course=bankernas-historia`,labelSv:`Kurs: Bankernas historia`,labelEn:`Course: The history of banking`,descriptionSv:`Från Riksbanken 1668 till IMF`,descriptionEn:`From the Riksbank 1668 to the IMF`}]},{moduleId:`mf-02-algoritmer-och-ai`,moduleTitle:`02 · Algoritmisk handel och AI – robotarna på marknaden`,moduleTitleEn:`02 · Algorithmic trading and AI – the robots in the market`,summary:`Vad algoritmisk handel och högfrekvenshandel är enligt MiFID II, vilka krav som gäller och hur ESMA, FSB och BIS ser på AI.`,summaryEn:`What algorithmic and high-frequency trading are under MiFID II, which requirements apply and how ESMA, the FSB and the BIS view AI.`,durationMinutes:14,topics:[`Algoritmisk handel`,`HFT`,`AI`,`MiFID II`,`Quiz`],topicsEn:[`Algorithmic trading`,`HFT`,`AI`,`MiFID II`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad algoritmisk handel och högfrekvenshandel är enligt EU:s regler,`,`• beskriva vilka krav som gäller för företag som handlar algoritmiskt,`,`• beskriva hur AI används i finanssektorn och vad myndigheterna följer.`,`# Vad är algoritmisk handel?`,`Enligt EU:s direktiv MiFID II är algoritmisk handel handel med finansiella instrument där en datoralgoritm automatiskt bestämmer orderns detaljer, till exempel om ordern ska läggas, när, till vilket pris, i vilken mängd och hur den hanteras efteråt. Datorn fattar besluten helt eller till största delen automatiskt.`,`**Högfrekvenshandel** (HFT) är en form av algoritmisk handel med tre kännetecken:`,`• infrastruktur som minimerar fördröjningar, till exempel servrar placerade nära handelsplatsen,`,`• systemet bestämmer order helt automatiskt för enskilda affärer,`,`• många meddelanden per dag i form av order, noteringar och makuleringar.`,`# Regler för robotarna`,`Ett värdepappersföretag som handlar algoritmiskt ska enligt MiFID II ha:`,`• effektiva system och riskkontroller som gör handelssystemen motståndskraftiga och med tillräcklig kapacitet,`,`• tydliga gränser och spärrar för handeln, så att felaktiga order stoppas,`,`• planer för kontinuitet och system som är testade och övervakade.`,`Företaget anmäler den algoritmiska handeln till tillsynsmyndigheten och handelsplatsen och kan behöva beskriva sina strategier, gränser och kontroller.`,`# Ledgern i handeln`,`Företaget för register som gör att myndigheten kan följa upp att reglerna följs.`,`Ett företag som använder högfrekvenshandel sparar exakta register i tidsordning över alla order, makuleringar, genomförda affärer och noteringar, och lämnar ut dem till myndigheten på begäran.`,`Varje robotorder blir alltså en post i en bok, precis som varje ägarbyte i VOC:s aktiebok.`,`# AI i finanssektorn`,`Finansiella stabilitetsrådet, FSB, beskriver fördelar med AI som effektivare drift, bättre regelefterlevnad, finansiella produkter som anpassas till kunden och avancerad dataanalys.`,`ESMA nämner kundsupport, upptäckt av bedrägerier, riskhantering, regelefterlevnad och stöd i rådgivning och förvaltning som användningsområden för AI hos värdepappersföretag.`,`BIS beskriver hur AI-modeller används inom kapitalförvaltning för att bedöma förhållandet mellan risk och avkastning och fördela portföljer.`,`# Det som myndigheterna följer`,`ESMA förväntar sig att företag som använder AI följer MiFID II, särskilt reglerna om organisation, uppträdande och skyldigheten att agera i kundens bästa intresse. ESMA lyfter fram fyra områden att bevaka:`,`• datakvalitet och snedvridning i algoritmerna,`,`• tydlighet i hur beslut fattas,`,`• ett balanserat beroende av AI hos både företag och kunder,`,`• integritet och säkerhet för de stora datamängder som AI behöver.`,`FSB pekar på fyra sårbarheter som kan öka systemrisken: beroende av ett fåtal leverantörer, samvariation på marknaderna, cyberrisker samt modellrisk, datakvalitet och styrning.`,`BIS beskriver att många aktörer som använder samma algoritmer kan förstärka flockbeteende och svängningar på marknaden.`,`Fördjupning om automation, risklimiter och övervakning kommer i kursen «AI-handel & riskramar».`,`# Sammanfattning`,`Algoritmer och AI är i dag en del av marknaderna. Reglerna kräver kontroller, gränser och register, och myndigheterna följer utvecklingen noga. Varje order lämnar ett spår i boken.`],quiz:[{id:`mf2-q1`,prompt:`Vad är algoritmisk handel enligt MiFID II?`,promptEn:`What is algorithmic trading under MiFID II?`,promptUk:`Що таке алгоритмічна торгівля за MiFID II?`,options:[xs(`a`,`All handel via internet`,!1,`All trading via the internet`,`Уся торгівля через інтернет`),xs(`b`,`Handel med kryptotillgångar`,!1,`Trading in crypto-assets`,`Торгівля криптоактивами`),xs(`c`,`Handel där en datoralgoritm automatiskt bestämmer orderns detaljer`,!0,`Trading where a computer algorithm automatically decides the order's details`,`Торгівля, де комп'ютерний алгоритм автоматично визначає деталі ордера`),xs(`d`,`Handel som bara sker på natten`,!1,`Trading that only happens at night`,`Торгівля, що відбувається лише вночі`)],explanation:`Definitionen gäller algoritmer som bestämmer om, när, till vilket pris och i vilken mängd en order läggs.`,explanationEn:`The definition covers algorithms that decide whether, when, at what price and in what quantity an order is placed.`,explanationUk:`Визначення стосується алгоритмів, які вирішують, чи, коли, за якою ціною і в якій кількості ставити ордер.`},{id:`mf2-q2`,prompt:`Vilket register ska ett företag med högfrekvenshandel spara?`,promptEn:`What record must a firm with high-frequency trading keep?`,promptUk:`Який реєстр має зберігати фірма з високочастотною торгівлею?`,options:[xs(`a`,`Exakta register i tidsordning över alla order, makuleringar, affärer och noteringar`,!0,`Exact records in time order of all orders, cancellations, trades and quotes`,`Точні записи в часовому порядку всіх ордерів, скасувань, угод і котирувань`),xs(`b`,`Bara de order som genomfördes`,!1,`Only the orders that were carried out`,`Лише виконані ордери`),xs(`c`,`En lista över kunderna`,!1,`A list of the customers`,`Список клієнтів`),xs(`d`,`Ett register över sina servrar`,!1,`A register of its servers`,`Реєстр своїх серверів`)],explanation:`Registren lämnas ut till myndigheten på begäran.`,explanationEn:`The records are handed to the authority on request.`,explanationUk:`Реєстри передають органу на вимогу.`},{id:`mf2-q3`,prompt:`Vad förväntar sig ESMA av företag som använder AI i investeringstjänster?`,promptEn:`What does ESMA expect of firms that use AI in investment services?`,promptUk:`Чого ESMA очікує від фірм, які використовують ШІ в інвестиційних послугах?`,options:[xs(`a`,`Att de slutar använda algoritmer`,!1,`That they stop using algorithms`,`Щоб вони припинили використовувати алгоритми`),xs(`b`,`Att de följer MiFID II, bland annat skyldigheten att agera i kundens bästa intresse`,!0,`That they follow MiFID II, including the duty to act in the client's best interest`,`Щоб вони дотримувалися MiFID II, зокрема обов'язку діяти в найкращому інтересі клієнта`),xs(`c`,`Att AI fattar alla beslut`,!1,`That AI makes every decision`,`Щоб ШІ ухвалював усі рішення`),xs(`d`,`Att kunderna själva kontrollerar AI`,!1,`That the customers themselves check the AI`,`Щоб клієнти самі перевіряли ШІ`)],explanation:`ESMA:s uttalande från 2024 betonar organisation, uppträdande och kundens bästa.`,explanationEn:`ESMA's statement from 2024 stresses organisation, conduct and the client's best interest.`,explanationUk:`Заява ESMA 2024 року підкреслює організацію, поведінку і найкращий інтерес клієнта.`},{id:`mf2-q4`,prompt:`Vilken sårbarhet lyfter FSB fram?`,promptEn:`Which vulnerability does the FSB highlight?`,promptUk:`Яку вразливість підкреслює FSB?`,options:[xs(`a`,`För få datorer i världen`,!1,`Too few computers in the world`,`Замало комп'ютерів у світі`),xs(`b`,`Att sedlar försvinner`,!1,`That notes disappear`,`Що банкноти зникають`),xs(`c`,`Att börser stänger på helger`,!1,`That exchanges close at weekends`,`Що біржі закриті на вихідних`),xs(`d`,`Beroende av ett fåtal leverantörer av AI-tjänster`,!0,`Dependence on a few suppliers of AI services`,`Залежність від небагатьох постачальників послуг ШІ`)],explanation:`FSB nämner leverantörskoncentration, samvariation på marknaderna, cyberrisker och modellrisk.`,explanationEn:`The FSB mentions supplier concentration, markets moving together, cyber risks and model risk.`,explanationUk:`FSB називає концентрацію постачальників, спільний рух ринків, кіберризики і модельний ризик.`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-01-fran-bocker-till-ledger`,labelSv:`Föregående: Från böckerna till ledgern`,labelEn:`Previous: From books to the ledger`}]},{moduleId:`mf-03-krypto`,moduleTitle:`03 · Krypto – en ledger som delas`,moduleTitleEn:`03 · Crypto – a ledger that is shared`,summary:`Vad en kryptotillgång är, hur Bitcoin för en gemensam bok, stablecoins och NFT, och EU:s MiCA-förordning.`,summaryEn:`What a crypto-asset is, how Bitcoin keeps a shared book, stablecoins and NFTs, and the EU MiCA Regulation.`,durationMinutes:14,topics:[`Kryptotillgångar`,`Bitcoin`,`Blockkedja`,`Stablecoins`,`MiCA`,`Quiz`],topicsEn:[`Crypto-assets`,`Bitcoin`,`Blockchain`,`Stablecoins`,`MiCA`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad en kryptotillgång är,`,`• beskriva hur Bitcoin använder en delad ledger,`,`• nämna olika typer av kryptotillgångar,`,`• berätta vad EU:s MiCA-förordning innebär.`,`# Vad är en kryptotillgång?`,`Finansinspektionen beskriver en kryptotillgång, ibland kallad kryptovaluta, som en digital representation av ett värde eller en rättighet som kan överföras och lagras elektroniskt med hjälp av blockkedjeteknik.`,`# Bitcoin och den delade boken`,`I oktober 2008 publicerade en person eller grupp under namnet Satoshi Nakamoto ett förslag till en digital valuta, Bitcoin. Nätverket startade 2009.`,`Förslaget beskriver elektroniska kontanter som skickas direkt mellan två parter via ett nätverk av datorer.`,`För att alla ska kunna se att samma mynt används en gång tillkännages transaktionerna offentligt, och deltagarna enas om en gemensam historik över i vilken ordning de kom in.`,`Nätverket tidsstämplar transaktionerna i en kedja av block. Kedjan blir ett register som kräver att allt arbete görs om för att ändras.`,`Här tar ledgern ett nytt steg: boken förs gemensamt av deltagarna i nätverket.`,`# Hur nya bitcoin skapas`,`Nya bitcoin skapas när datorer i nätverket löser ett matematiskt problem, så kallad mining. Ungefär vart fjärde år halveras antalet nya bitcoin per block. Det högsta antalet bitcoin är något under 21 miljoner, och 2025 fanns nästan 20 miljoner.`,`# Olika typer av kryptotillgångar`,`Enligt Finansinspektionen:`,`• **Bitcoin** är den mest kända och största kryptotillgången.`,`• **Stablecoins** följer värdet på en eller flera officiella valutor eller andra tillgångar, till exempel guld.`,`• **NFT** (icke-fungibla tokens) kan beskrivas som ett ägarbevis, till exempel för digital konst.`,`ECB skiljer kryptotillgångar från centralbankspengar: centralbanker har i uppdrag att bevara pengarnas värde, medan kryptotillgångar backas och förvaltas utanför centrala institutioner.`,`# Regler: MiCA`,`MiCA-förordningen (Markets in Crypto-Assets) trädde i kraft i juni 2023. Under 2024 började den tillämpas. Den ger enhetliga regler för företag som ger ut eller erbjuder tjänster med kryptotillgångar, stärker konsumentskyddet, ökar insynen i produkternas miljöpåverkan och minskar risken att kryptotillgångar används i brottslig verksamhet.`,`ESMA för ett centralt register över vitböcker för kryptotillgångar, godkända kryptotjänsteleverantörer och aktörer som bryter mot reglerna.`,`# Så ser myndigheterna på risken`,`EU:s tillsynsmyndigheter ESMA, EBA och EIOPA beskriver de flesta kryptotillgångar som volatila och mycket riskfyllda. Priset kan stiga och falla snabbt.`,`Finansinspektionen beskriver att de flesta kryptotillgångar innebär hög risk att förlora pengar.`,`# Sammanfattning`,`Kryptotillgångar bygger på en ledger som förs gemensamt i ett nätverk. Bitcoin var först, och i dag finns också stablecoins och NFT. I EU gäller MiCA-förordningen.`],quiz:[{id:`mf3-q1`,prompt:`Hur beskriver Finansinspektionen en kryptotillgång?`,promptEn:`How does Finansinspektionen describe a crypto-asset?`,promptUk:`Як Finansinspektionen описує криптоактив?`,options:[xs(`a`,`En aktie i en bank`,!1,`A share in a bank`,`Акція банку`),xs(`b`,`En sedel från Riksbanken`,!1,`A note from the Riksbank`,`Банкнота Риксбанку`),xs(`c`,`En digital representation av ett värde eller en rättighet som överförs och lagras med blockkedjeteknik`,!0,`A digital representation of a value or a right that is transferred and stored with blockchain technology`,`Цифрове представлення вартості або права, яке передають і зберігають за допомогою блокчейну`),xs(`d`,`Ett sparkonto`,!1,`A savings account`,`Ощадний рахунок`)],explanation:`Definitionen finns på FI:s konsumentsida om kryptotillgångar.`,explanationEn:`The definition is on FI's consumer page about crypto-assets.`,explanationUk:`Визначення є на споживчій сторінці FI про криптоактиви.`},{id:`mf3-q2`,prompt:`Hur enas deltagarna i Bitcoin om vilka transaktioner som gäller?`,promptEn:`How do participants in Bitcoin agree which transactions count?`,promptUk:`Як учасники Bitcoin домовляються, які транзакції дійсні?`,options:[xs(`a`,`En bank bestämmer`,!1,`A bank decides`,`Вирішує банк`),xs(`b`,`Transaktionerna tillkännages offentligt och deltagarna enas om en gemensam historik`,!0,`The transactions are announced publicly and the participants agree on a shared history`,`Транзакції оголошують публічно, і учасники погоджують спільну історію`),xs(`c`,`Varje användare för en egen bok`,!1,`Each user keeps a private book`,`Кожен користувач веде власну книгу`),xs(`d`,`Riksbanken godkänner varje transaktion`,!1,`The Riksbank approves every transaction`,`Риксбанк схвалює кожну транзакцію`)],explanation:`Nakamoto beskriver en gemensam historik över i vilken ordning transaktionerna kom in.`,explanationEn:`Nakamoto describes a shared history of the order in which the transactions arrived.`,explanationUk:`Накамото описує спільну історію того, в якому порядку надійшли транзакції.`},{id:`mf3-q3`,prompt:`Vad kännetecknar en stablecoin?`,promptEn:`What marks a stablecoin?`,promptUk:`Що відрізняє stablecoin?`,options:[xs(`a`,`Den följer värdet på en eller flera officiella valutor eller andra tillgångar`,!0,`It follows the value of one or more official currencies or other assets`,`Він іде за вартістю однієї чи кількох офіційних валют або інших активів`),xs(`b`,`Den ges ut av en centralbank`,!1,`It is issued by a central bank`,`Його випускає центральний банк`),xs(`c`,`Den är en aktie`,!1,`It is a share`,`Це акція`),xs(`d`,`Den kan bara användas offline`,!1,`It can only be used offline`,`Ним можна користуватися лише офлайн`)],explanation:`Finansinspektionen beskriver stablecoins som kryptotillgångar som följer en valuta eller en annan tillgång.`,explanationEn:`Finansinspektionen describes stablecoins as crypto-assets that follow a currency or another asset.`,explanationUk:`Finansinspektionen описує stablecoin як криптоактиви, що йдуть за валютою або іншим активом.`},{id:`mf3-q4`,prompt:`Vad gör MiCA-förordningen?`,promptEn:`What does the MiCA regulation do?`,promptUk:`Що робить регламент MiCA?`,options:[xs(`a`,`Den inför euron i Sverige`,!1,`It introduces the euro in Sweden`,`Він запроваджує євро у Швеції`),xs(`b`,`Den gäller bara aktier`,!1,`It applies only to shares`,`Він стосується лише акцій`),xs(`c`,`Den bestämmer priset på bitcoin`,!1,`It sets the price of bitcoin`,`Він визначає ціну bitcoin`),xs(`d`,`Den ger enhetliga regler i EU för företag som ger ut eller erbjuder tjänster med kryptotillgångar`,!0,`It gives uniform rules in the EU for firms that issue crypto-assets or offer services in them`,`Він дає єдині правила в ЄС для фірм, які випускають криптоактиви або надають послуги з ними`)],explanation:`MiCA stärker bland annat konsumentskyddet och insynen.`,explanationEn:`MiCA strengthens consumer protection and transparency, among other things.`,explanationUk:`MiCA посилює, серед іншого, захист споживачів і прозорість.`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-02-algoritmer-och-ai`,labelSv:`Föregående: Algoritmer och AI`,labelEn:`Previous: Algorithms and AI`}]},{moduleId:`mf-04-cbdc`,moduleTitle:`04 · CBDC – e-kronan och den digitala euron`,moduleTitleEn:`04 · CBDC – the e-krona and the digital euro`,summary:`Var arbetet med e-kronan står, hur den digitala euron är tänkt att fungera och när den kan komma, och en jämförelse med krypto och bankpengar.`,summaryEn:`Where work on the e-krona stands, how the digital euro is meant to work and when it may arrive, and a comparison with crypto and bank money.`,durationMinutes:14,topics:[`CBDC`,`E-krona`,`Digital euro`,`Centralbankspengar`,`Quiz`],topicsEn:[`CBDC`,`E-krona`,`Digital euro`,`Central bank money`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad en CBDC (digitala centralbankspengar) är,`,`• berätta var arbetet med e-kronan står,`,`• beskriva hur den digitala euron är tänkt att fungera och när den kan komma,`,`• jämföra krypto, CBDC och bankpengar.`,`# Vad är en CBDC?`,`CBDC står för central bank digital currency, digitala centralbankspengar.`,`I Sverige har allmänheten i dag tillgång till kronor i två former: kontanter från staten och digitala pengar från privata aktörer, främst inlåning i banker.`,`# E-kronan`,`E-kronor skulle vara svenska, digitala kronor utgivna av Riksbanken. De skulle komplettera kontanterna.`,`Enligt Riksbanken kan e-kronor stärka motståndskraften på betalningsmarknaden, fungera offline, öka konkurrensen och bidra till finansiell inkludering.`,`Riksbanken startade e-kronaprojektet 2017. Från 2020 testade e-kronapiloten en möjlig teknisk plattform. Projektet och piloten avslutades 2023.`,`Att införa e-kronor är ett politiskt beslut. I Betalningsrapport 2026 föreslog Riksbanken att en utredning om nödvändiga lagändringar tillsätts, så att en e-krona kan införas inom rimlig tid om riksdagen beslutar det.`,`# Den digitala euron`,`Den digitala euron skulle vara en digital form av kontanter, utgiven av centralbanken och tillgänglig för alla i euroområdet. Den skulle komplettera sedlar och mynt.`,`Enligt ECB:`,`• Den digitala euron skulle vara lagligt betalningsmedel, och en digital euro är alltid värd en euro.`,`• Den skulle kunna användas både online och offline. Vid betalningar offline känner bara betalaren och mottagaren till transaktionsuppgifterna.`,`• Personuppgifterna skyddas: Eurosystemet skulle hålla isär transaktionerna och enskilda personers identitet.`,`• Den skulle kunna användas fritt: var, när och med vem bestämmer användaren. Villkorade betalningar, till exempel betalning vid leverans, skulle vara möjliga.`,`• Innehavet är räntefritt, precis som kontanter i plånboken.`,`# Ledgern i en CBDC`,`Den digitala euron är tänkt att gå på en central avvecklingsplattform där Eurosystemet hanterar och verifierar alla transaktioner och innehav. Plattformen bygger på vedertagna standarder och använder viktiga designprinciper från tekniken för distribuerade ledgers.`,`Här förs boken alltså av centralbanken, medan kryptots bok förs gemensamt i ett nätverk.`,`# Var står den digitala euron?`,`Förberedelsefasen pågick från november 2023 till oktober 2025. I oktober 2025 beslutade ECB-rådet att projektet går vidare till nästa fas.`,`En pilot med en betaversion planeras starta under andra halvåret 2027 och pågå i tolv månader.`,`ECB siktar på att vara redo för en möjlig första utgivning under 2029, förutsatt att EU-förordningen om den digitala euron antas före slutet av 2026.`,`# Krypto, CBDC och bankpengar`,`• Vem ger ut? – Krypto: Ett nätverk av deltagare, till exempel Bitcoin · CBDC: Centralbanken · Bankpengar: Affärsbanken, när den lånar ut`,`• Vem för boken? – Krypto: Deltagarna i nätverket · CBDC: Centralbanken, i den digitala euron via en central plattform · Bankpengar: Banken`,`• Värde – Krypto: Kan svänga kraftigt · CBDC: En digital euro är alltid värd en euro · Bankpengar: Kronor på kontot kan växlas mot centralbankspengar, så en krona är lika mycket värd i alla banker`,`# Sammanfattning`,`En CBDC är centralbankspengar i digital form. Riksbanken följer arbetet med den digitala euron noga, och ECB siktar på att vara redo 2029.`],quiz:[{id:`mf4-q1`,prompt:`Vem skulle ge ut e-kronor?`,promptEn:`Who would issue e-kronor?`,promptUk:`Хто випускав би е-крони?`,options:[xs(`a`,`Affärsbankerna`,!1,`The commercial banks`,`Комерційні банки`),xs(`b`,`ECB`,!1,`The ECB`,`ЄЦБ`),xs(`c`,`Riksbanken`,!0,`The Riksbank`,`Риксбанк`),xs(`d`,`Ett kryptonätverk`,!1,`A crypto network`,`Криптомережа`)],explanation:`E-kronor skulle vara digitala kronor utgivna av Riksbanken.`,explanationEn:`E-kronor would be digital kronor issued by the Riksbank.`,explanationUk:`Е-крони були б цифровими кронами, випущеними Риксбанком.`},{id:`mf4-q2`,prompt:`Vem beslutar om Sverige ska införa e-kronor?`,promptEn:`Who decides whether Sweden should introduce e-kronor?`,promptUk:`Хто вирішує, чи запроваджувати Швеції е-крони?`,options:[xs(`a`,`Politikerna, genom riksdagen`,!0,`The politicians, through the Riksdag`,`Політики, через риксдаг`),xs(`b`,`Bankerna`,!1,`The banks`,`Банки`),xs(`c`,`ECB`,!1,`The ECB`,`ЄЦБ`),xs(`d`,`Finansinspektionen`,!1,`Finansinspektionen`,`Finansinspektionen`)],explanation:`Riksbanken beskriver införandet som ett politiskt beslut.`,explanationEn:`The Riksbank describes the introduction as a political decision.`,explanationUk:`Риксбанк описує запровадження як політичне рішення.`},{id:`mf4-q3`,prompt:`När siktar ECB på att vara redo för en första utgivning av den digitala euron?`,promptEn:`When does the ECB aim to be ready for a first possible issuance of the digital euro?`,promptUk:`Коли ЄЦБ прагне бути готовим до можливого першого випуску цифрового євро?`,options:[xs(`a`,`2025`,!1,`2025`,`2025`),xs(`b`,`2027`,!1,`2027`,`2027`),xs(`c`,`2040`,!1,`2040`,`2040`),xs(`d`,`2029, om EU-förordningen antas före slutet av 2026`,!0,`2029, if the EU regulation is adopted before the end of 2026`,`2029, якщо регламент ЄС ухвалять до кінця 2026 року`)],explanation:`Piloten planeras till andra halvåret 2027, och målet för en möjlig utgivning är 2029.`,explanationEn:`The pilot is planned for the second half of 2027, and the aim for a possible issuance is 2029.`,explanationUk:`Пілот планують на друге півріччя 2027 року, а ціль можливого випуску — 2029.`},{id:`mf4-q4`,prompt:`Vilket påstående om den digitala euron stämmer enligt ECB?`,promptEn:`Which statement about the digital euro is right according to the ECB?`,promptUk:`Яке твердження про цифрове євро правильне згідно з ЄЦБ?`,options:[xs(`a`,`Den betalar hög ränta`,!1,`It pays a high interest rate`,`Воно дає високий відсоток`),xs(`b`,`Den kan användas offline, och en digital euro är alltid värd en euro`,!0,`It can be used offline, and a digital euro is always worth one euro`,`Ним можна користуватися офлайн, і одне цифрове євро завжди варте одного євро`),xs(`c`,`Den är en kryptotillgång`,!1,`It is a crypto-asset`,`Це криптоактив`),xs(`d`,`Den ersätter sedlarna`,!1,`It replaces the notes`,`Воно замінює банкноти`)],explanation:`Den digitala euron skulle fungera online och offline och komplettera kontanterna.`,explanationEn:`The digital euro would work online and offline and complement cash.`,explanationUk:`Цифрове євро працювало б онлайн і офлайн і доповнювало готівку.`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-03-krypto`,labelSv:`Föregående: Krypto`,labelEn:`Previous: Crypto`}]},{moduleId:`mf-05-ico-och-tokens`,moduleTitle:`05 · ICO och tokens – nya andelar i boken`,moduleTitleEn:`05 · ICOs and tokens – new shares in the book`,summary:`Vad en ICO är, olika slags tokens och vitböcker enligt MiCA. Fördjupning finns i kursen ICO & tokenerbjudanden.`,summaryEn:`What an ICO is, different kinds of tokens and disclosures under MiCA. More in the course ICO & token offerings.`,durationMinutes:10,topics:[`ICO`,`Tokens`,`Vitbok`,`MiCA`,`Quiz`],topicsEn:[`ICO`,`Tokens`,`Disclosure`,`MiCA`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad en ICO är,`,`• beskriva olika slags tokens,`,`• berätta var du hittar vitböcker enligt MiCA.`,`# Vad är en ICO?`,`En ICO (initial coin offering) är ett sätt att ta in pengar från allmänheten med hjälp av så kallade coins eller tokens. Den kallas också token sale. Ett företag eller en person ger ut tokens och säljer dem mot vanliga valutor som euro eller, oftare, mot kryptotillgångar som bitcoin eller ether.`,`ICO:er används för att finansiera olika projekt, bland annat företag som bygger på blockkedjor eller distribuerade ledgers.`,`# Olika slags tokens`,`Enligt ESMA varierar tokens mellan olika ICO:er:`,`• en del ger tillgång till en tjänst eller produkt som utgivaren utvecklar,`,`• en del ger rösträtt eller en andel av framtida intäkter, som kan utebli,`,`• en del handlas på särskilda handelsplatser efter utgivningen.`,`Jämför med VOC 1602: andelen fördes in i kompaniets bok. Vid en ICO förs de nya tokens in i en digital ledger.`,`# Vitböcker enligt MiCA`,`Enligt MiCA lämnas informationen om en kryptotillgång i en vitbok. ESMA publicerar ett centralt register över vitböcker för kryptotillgångar.`,`Utgivaren eller den som erbjuder kryptotillgången ansvarar ensam för innehållet i vitboken. Registret är en förteckning, och vitböckerna publiceras på utgivarens eget ansvar.`,`Sedan den 23 december 2025 ska vitböcker vara maskinläsbara i formatet iXBRL.`,`# Myndigheternas syn`,`ESMA varnade redan 2017 för att ICO:er är mycket riskfyllda och spekulativa och att priset på tokens ofta svänger kraftigt.`,`Vitbok, tokenomics, reglering, bedrägerimönster och skillnaden mot en börsintroduktion går vi igenom i kursen «ICO & tokenerbjudanden».`,`# Sammanfattning`,`En ICO skapar nya tokens i en digital ledger, ungefär som VOC förde in nya andelar i sin bok. Under MiCA finns informationen i en vitbok som utgivaren ansvarar för.`],quiz:[{id:`mf5-q1`,prompt:`Vad är en ICO enligt ESMA?`,promptEn:`What is an ICO according to ESMA?`,promptUk:`Що таке ICO згідно з ESMA?`,options:[xs(`a`,`En börsintroduktion av en bank`,!1,`A stock-exchange listing of a bank`,`Біржовий вихід банку`),xs(`b`,`Ett sätt att ta in pengar från allmänheten med coins eller tokens`,!0,`A way to raise money from the public with coins or tokens`,`Спосіб зібрати гроші від публіки монетами або токенами`),xs(`c`,`En centralbanksvaluta`,!1,`A central-bank currency`,`Валюта центрального банку`),xs(`d`,`En försäkring`,!1,`An insurance policy`,`Страховий поліс`)],explanation:`ICO kallas också token sale.`,explanationEn:`ICO is also called a token sale.`,explanationUk:`ICO також називають token sale.`},{id:`mf5-q2`,prompt:`Vem ansvarar för innehållet i en vitbok enligt MiCA?`,promptEn:`Who is responsible for the content of a white paper under MiCA?`,promptUk:`Хто відповідає за зміст white paper за MiCA?`,options:[xs(`a`,`Utgivaren eller den som erbjuder kryptotillgången`,!0,`The issuer or the person offering the crypto-asset`,`Емітент або той, хто пропонує криптоактив`),xs(`b`,`ESMA`,!1,`ESMA`,`ESMA`),xs(`c`,`Riksbanken`,!1,`The Riksbank`,`Риксбанк`),xs(`d`,`Köparen`,!1,`The buyer`,`Покупець`)],explanation:`Vitböcker i ESMA:s register är utgivarens ansvar.`,explanationEn:`White papers in ESMA's register are the issuer's responsibility.`,explanationUk:`White paper у реєстрі ESMA — відповідальність емітента.`},{id:`mf5-q3`,prompt:`Vilken koppling finns mellan en ICO och VOC:s aktiebok?`,promptEn:`What link is there between an ICO and the VOC's share book?`,promptUk:`Який зв'язок між ICO і акціонерною книгою VOC?`,options:[xs(`a`,`Båda gavs ut av Riksbanken`,!1,`Both were issued by the Riksbank`,`Обидва випустив Риксбанк`),xs(`b`,`Båda handlades bara offline`,!1,`Both were traded only offline`,`Обидва торгувалися лише офлайн`),xs(`c`,`Båda för in nya andelar i en bok, VOC i en pappersbok och en ICO i en digital ledger`,!0,`Both enter new shares in a book: the VOC in a paper book and an ICO in a digital ledger`,`Обидва вносять нові частки в книгу: VOC у паперову, ICO в цифрову`),xs(`d`,`Båda saknade ägare`,!1,`Both had no owner`,`В обох не було власника`)],explanation:`VOC förde in insatserna i sina böcker, och en ICO skapar tokens i en ledger.`,explanationEn:`The VOC entered the contributions in its books, and an ICO creates tokens in a ledger.`,explanationUk:`VOC вносила внески у свої книги, а ICO створює токени в книзі.`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-04-cbdc`,labelSv:`Föregående: CBDC`,labelEn:`Previous: CBDC`}]},{moduleId:`mf-06-sjalvforvar-kall-planbok`,moduleTitle:`06 · Självförvar och kall plånbok`,moduleTitleEn:`06 · Self-custody and cold wallets`,summary:`Självförvar, varm och kall plånbok, varför offline-nycklar minskar attackytan och hur du gör en säker backup av återställningsfrasen.`,summaryEn:`Self-custody, hot and cold wallets, why offline keys reduce the attack surface and how to back up a recovery phrase safely.`,durationMinutes:14,topics:[`Självförvar`,`Plånbok`,`Kall förvaring`,`Återställningsfras`,`Quiz`],topicsEn:[`Self-custody`,`Wallet`,`Cold storage`,`Recovery phrase`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad självförvar innebär,`,`• beskriva skillnaden mellan varm och kall plånbok,`,`• förklara varför nycklar som förvaras offline minskar attackytan,`,`• göra en säker backup av en återställningsfras.`,`# Nyckeln till din post i boken`,`Tempelherrarna och VOC förde böckerna åt sina kunder, och i dag för bankerna boken. I en delad ledger för användarna in sina transaktioner själva, och de hanterar och lagrar själva sina privata nycklar, ofta i en plånbok.`,`# Nycklar och plånböcker`,`En privat nyckel är en hemlig kod som bevisar att du äger något i blockkedjan.`,`En plånbok är ett program som skapar, hanterar, lagrar eller använder privata och publika nycklar. Den kan vara mjukvara eller en särskild hårdvaruenhet.`,`# Självförvar`,`Du kan förvara nycklarna själv eller låta en förvarare sköta dem åt dig.`,`Vid självförvar sköter du allt lokalt: du skapar nycklarna, förvarar dem säkert, gör backup, kan återställa dem och granskar och signerar varje transaktion. Du väljer själv säkerhetsnivån, och ditt godkännande krävs före varje transaktion.`,`Självförvar innebär också fullt ansvar för nycklarna. Därför är en genomtänkt backup och noggrann granskning av varje transaktion en del av vardagen.`,`# Varm och kall plånbok`,`NIST delar in plånböcker efter om de är uppkopplade mot internet.`,`• Anslutning – Varm plånbok: Uppkopplad mot internet · Kall plånbok: Offline, frånkopplad från internet`,`• Används för – Varm plånbok: Snabb åtkomst, mindre belopp och pengar i rörelse · Kall plånbok: Hög säkerhet, större belopp som ligger still`,`• Signering – Varm plånbok: Direkt i den uppkopplade enheten · Kall plånbok: Kräver ett fysiskt steg, till exempel en knapptryckning, en lokal PIN-kod eller en QR-kod`,`• Exempel på form – Varm plånbok: Program i telefonen eller datorn · Kall plånbok: Särskild hårdvaruplånbok eller en dator som hålls helt isolerad från nätverk`,`De två typerna används ofta för olika ändamål: den varma för pengar i rörelse och den kalla för det som ligger still. NIST beskriver också ett mellanled som kan lägga in tidsfördröjning, beloppsgränser eller flera signaturer före uttag.`,`# Varför offline-nycklar minskar attackytan`,`Attackytan är alla punkter där en angripare kan försöka ta sig in i ett system, påverka det eller hämta data ur det.`,`En hårdvaruplånbok förvarar de privata nycklarna offline. Nyckeln stannar hela tiden lokalt på enheten.`,`Att hålla privata nycklarna offline minskar risken för intrång kraftigt, även om en angripare skulle ta kontroll över din dator.`,`En kall plånbok kräver dessutom ett fysiskt steg för att signera, till exempel en knapptryckning på enheten.`,`Nyckeln finns alltså på färre ställen som går att nå via internet. Attackytan blir mindre.`,`Privata nycklar ska skyddas mot obehörigt röjande. Det gäller all kryptografi, också i banker och myndigheter.`,`# Backup av återställningsfrasen`,`Återställningsfrasen (seed phrase) är en lista med ord som du får när plånboken skapas. Med den kan du ta dig tillbaka in i plånboken. Med en och samma fras kan alla konton i plånboken återställas på en gång.`,`Frasen är huvudnyckeln till plånboken: den som har frasen kommer åt alla konton.`,`Så gör du en säker backup:`,`1. **Skriv ned frasen** och förvara kopian på en säker plats som bara du har tillgång till. En papperskopia är en vanlig form av backup.`,`2. **Skydda backupen mot förlust, stöld och skador.** Det gäller både papperskopior och digitala kopior.`,`3. **Håll frasen offline.** Skriv den för hand i stället för att ta en skärmdump. Skärmdumpar kan synkas till molnet, och nycklar hämtade från molnet är en vanlig attackväg.`,`4. **Behåll frasen för dig själv.** Frasen och de privata nycklarna stannar hos dig. Seriösa tjänster, supportpersonal och webbplatser sköter sitt arbete med andra uppgifter.`,`5. **Dubbelkolla mottagaradressen** innan du skickar en transaktion.`,`6. **Håll enheter och program uppdaterade**, använd starka och unika lösenord och logga in via säkra nätverk.`,`# Sammanfattning`,`Vid självförvar är det du som håller nyckeln till din post i ledgern. En kall plånbok håller nyckeln offline, och en väl förvarad återställningsfras gör att du alltid kan komma tillbaka in.`],quiz:[{id:`mf6-q1`,prompt:`Vad innebär självförvar?`,promptEn:`What does self-custody mean?`,promptUk:`Що означає самостійне зберігання?`,options:[xs(`a`,`Banken förvarar allt åt dig`,!1,`The bank stores everything for you`,`Банк зберігає все за тебе`),xs(`b`,`Nycklarna ligger hos en börs`,!1,`The keys sit at an exchange`,`Ключі лежать на біржі`),xs(`c`,`Du delar nycklarna med supporten`,!1,`You share the keys with support`,`Ти ділиш ключі з підтримкою`),xs(`d`,`Du skapar, förvarar och säkerhetskopierar dina nycklar själv och godkänner varje transaktion`,!0,`You create, store and back up your keys yourself and approve every transaction`,`Ти сам створюєш, зберігаєш і копіюєш ключі і схвалюєш кожну транзакцію`)],explanation:`Vid självförvar ligger nyckelhantering, backup och signering hos användaren.`,explanationEn:`In self-custody, key handling, backup and signing sit with the user.`,explanationUk:`При самостійному зберіганні ключі, резервна копія і підпис — у користувача.`},{id:`mf6-q2`,prompt:`Vad kännetecknar en kall plånbok?`,promptEn:`What marks a cold wallet?`,promptUk:`Що відрізняє холодний гаманець?`,options:[xs(`a`,`Den är alltid uppkopplad`,!1,`It is always online`,`Він завжди онлайн`),xs(`b`,`Den används bara för små belopp`,!1,`It is used only for small amounts`,`Його використовують лише для малих сум`),xs(`c`,`Nycklarna förvaras offline och signering kräver ett fysiskt steg`,!0,`The keys are stored offline and signing needs a physical step`,`Ключі зберігають офлайн, і підпис потребує фізичного кроку`),xs(`d`,`Den sköts av en bank`,!1,`A bank runs it`,`Ним керує банк`)],explanation:`En kall plånbok är frånkopplad från internet och kräver till exempel en knapptryckning eller en lokal PIN-kod för att signera.`,explanationEn:`A cold wallet is disconnected from the internet and needs, for example, a button press or a local PIN to sign.`,explanationUk:`Холодний гаманець від'єднаний від інтернету і для підпису потребує, наприклад, натискання кнопки або локального PIN.`},{id:`mf6-q3`,prompt:`Varför minskar offline-nycklar attackytan?`,promptEn:`Why do offline keys reduce the attack surface?`,promptUk:`Чому офлайнові ключі зменшують поверхню атаки?`,options:[xs(`a`,`Nyckeln finns på färre ställen som går att nå via internet, även om datorn angrips`,!0,`The key exists in fewer places that can be reached via the internet, even if the computer is attacked`,`Ключ є в меншій кількості місць, досяжних через інтернет, навіть якщо комп'ютер атаковано`),xs(`b`,`De gör transaktioner snabbare`,!1,`They make transactions faster`,`Вони прискорюють транзакції`),xs(`c`,`De ersätter återställningsfrasen`,!1,`They replace the recovery phrase`,`Вони замінюють фразу відновлення`),xs(`d`,`De gör nyckeln synlig för alla`,!1,`They make the key visible to everyone`,`Вони роблять ключ видимим для всіх`)],explanation:`Att hålla privata nycklar offline minskar risken för intrång kraftigt, även om en angripare tar kontroll över datorn.`,explanationEn:`Keeping private keys offline sharply reduces the risk of intrusion, even if an attacker takes control of the computer.`,explanationUk:`Тримання приватних ключів офлайн різко зменшує ризик вторгнення, навіть якщо зловмисник отримає контроль над комп'ютером.`},{id:`mf6-q4`,prompt:`Hur gör du en säker backup av återställningsfrasen?`,promptEn:`How do you make a safe backup of the recovery phrase?`,promptUk:`Як зробити безпечну копію фрази відновлення?`,options:[xs(`a`,`Tar en skärmdump som sparas i molnet`,!1,`Take a screenshot that is saved in the cloud`,`Зробити знімок екрана, що зберігається в хмарі`),xs(`b`,`Mejlar den till supporten`,!1,`Email it to support`,`Надіслати її підтримці`),xs(`c`,`Delar den i en chatt`,!1,`Share it in a chat`,`Поділитися нею в чаті`),xs(`d`,`Skriver ned den och förvarar kopian säkert, för dig själv`,!0,`Write it down and store the copy safely, for yourself`,`Записати її і зберігати копію безпечно, для себе`)],explanation:`Frasen är huvudnyckeln till plånboken. Skriv ned den, håll den offline och behåll den för dig själv.`,explanationEn:`The phrase is the master key to the wallet. Write it down, keep it offline and keep it to yourself.`,explanationUk:`Фраза — головний ключ гаманця. Запиши її, тримай офлайн і лиши собі.`}],relatedLinks:[{to:`/tradingskolan?course=historia&lesson=hist-05-bokforing-verktyg`,labelSv:`Marknadens historia: Bokföring och spår`,labelEn:`Market history: Bookkeeping and trails`,descriptionSv:`Handelsböcker och dubbel bokföring`,descriptionEn:`Ledgers and double-entry bookkeeping`},{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-05-ico-och-tokens`,labelSv:`Föregående: ICO och tokens`,labelEn:`Previous: ICOs and tokens`}]},{moduleId:`mf-07-framtiden-enligt-kallorna`,moduleTitle:`07 · Framtiden enligt institutionerna`,moduleTitleEn:`07 · The future according to the institutions`,summary:`BIS unified ledger och tokenisering, ECB:s och Riksbankens planer, ESMA:s tillsyn av AI och tokenisering – och ledgerns tidslinje.`,summaryEn:`The BIS unified ledger and tokenisation, ECB and Riksbank plans, ESMA supervision of AI and tokenisation – and the ledger timeline.`,durationMinutes:12,topics:[`Tokenisering`,`Unified ledger`,`CBDC`,`AI-tillsyn`,`Tidslinje`,`Quiz`],topicsEn:[`Tokenisation`,`Unified ledger`,`CBDC`,`AI supervision`,`Timeline`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• återge hur BIS beskriver framtidens penning- och finanssystem,`,`• nämna de planer som ECB, Riksbanken och ESMA själva har publicerat,`,`• följa ledgerns tidslinje från 1100-talet till i dag.`,`Alla framtidsbilder i lektionen kommer från institutionernas egna texter. Kursen återger dem.`,`# BIS: en «unified ledger»`,`BIS presenterade 2023 en ritning för det framtida penningsystemet. Tokenisering av pengar och tillgångar har enligt BIS stor potential, och samma genomgång tar upp risken att nya pengar inte håller lika värde, inte kan anpassas i mängd eller inte skyddas mot brott. En ny typ av finansiell infrastruktur, en «unified ledger», skulle kunna samla centralbankspengar, tokeniserade bankinsättningar och tokeniserade tillgångar på en programmerbar plattform.`,`Flera ledgers med olika användningsområden skulle kunna finnas samtidigt och kopplas ihop, enligt BIS.`,`# BIS 2025: nästa generations system`,`BIS beskriver tokenisering som en innovation som både förbättrar det gamla och möjliggör det nya, till exempel inom betalningar mellan länder och värdepappersmarknader.`,`Enligt BIS kan tokeniserade plattformar med centralbanksreserver, bankpengar och statsobligationer i centrum lägga grunden för nästa generations penning- och finanssystem.`,`BIS prövar stablecoins mot tre krav för ett penningsystem: att alla pengar är lika mycket värda (singleness), att penningmängden kan anpassas efter behovet (elasticity) och att systemet skyddas mot brott (integrity). BIS bedömer att stablecoins uppfyller dessa krav i otillräcklig grad för att bära penningsystemet.`,`# Centralbankernas och myndigheternas planer`,`• **ECB:** en pilot med den digitala euron under andra halvåret 2027 och beredskap för en möjlig första utgivning 2029, om EU-förordningen antas före slutet av 2026.`,`• **Riksbanken:** följer arbetet med den digitala euron och har föreslagit en utredning om de lagändringar som behövs för en e-krona.`,`• **ESMA:** inför från 2027 en ny prioritering i tillsynen för digital innovation, med fokus först på hur företagen använder AI och tokenisering.`,`• **FSB:** rekommenderar att myndigheter förbättrar övervakningen av AI, prövar om regelverken räcker till och stärker sin egen förmåga, bland annat med AI-verktyg.`,`• **BIS:** uppmanar centralbanker att samarbeta i en gemenskap där de delar kunskap, data och AI-verktyg.`,`# Ledgerns tidslinje`,`• 1119–1120 – Tempelherreorden grundas`,`• 1235 – Tempelherrarna betalar ut i Paris mot en inbetalning i London`,`• 1602 – VOC grundas, aktieägarna förs in i kompaniets böcker`,`• 2008 – Satoshi Nakamoto publicerar förslaget till Bitcoin`,`• 2009 – Bitcoinnätverket startar`,`• 2017 – Riksbanken startar e-kronaprojektet`,`• 2023 – MiCA träder i kraft och BIS presenterar idén om en unified ledger`,`• 2025 – ECB:s förberedelsefas för den digitala euron avslutas`,`• 2027 – Planerad pilot med den digitala euron och ESMA:s nya tillsynsprioritering`,`• 2029 – ECB:s mål för en möjlig första utgivning av den digitala euron`,`# Sammanfattning`,`Från tempelherrarnas konton till en möjlig unified ledger handlar det om samma sak: en betrodd bok över vem som äger vad. Institutionerna beskriver en framtid med tokenisering, digitala centralbankspengar och AI under tillsyn.`],quiz:[{id:`mf7-q1`,prompt:`Vad är en «unified ledger» enligt BIS?`,promptEn:`What is a unified ledger according to the BIS?`,promptUk:`Що таке unified ledger згідно з BIS?`,options:[xs(`a`,`En ny kryptovaluta`,!1,`A new cryptocurrency`,`Нова криптовалюта`),xs(`b`,`En plattform som samlar centralbankspengar, tokeniserade bankinsättningar och tokeniserade tillgångar`,!0,`A platform that gathers central-bank money, tokenised bank deposits and tokenised assets`,`Платформа, що збирає гроші центрального банку, токенізовані банківські депозити і токенізовані активи`),xs(`c`,`En bokföringsbok i en bank`,!1,`A bookkeeping book in a bank`,`Бухгалтерська книга в банку`),xs(`d`,`En aktiebok från VOC`,!1,`A share book from the VOC`,`Акціонерна книга VOC`)],explanation:`BIS beskrev idén 2023 som en ny typ av finansiell infrastruktur.`,explanationEn:`The BIS described the idea in 2023 as a new kind of financial infrastructure.`,explanationUk:`BIS описав ідею 2023 року як новий тип фінансової інфраструктури.`},{id:`mf7-q2`,prompt:`Vilka tre krav prövar BIS stablecoins mot?`,promptEn:`Which three requirements does the BIS test stablecoins against?`,promptUk:`Проти яких трьох вимог BIS перевіряє stablecoin?`,options:[xs(`a`,`Pris, volym och hastighet`,!1,`Price, volume and speed`,`Ціна, обсяг і швидкість`),xs(`b`,`Ränta, skatt och avgift`,!1,`Interest, tax and fee`,`Відсоток, податок і комісія`),xs(`c`,`Singleness, elasticity och integrity`,!0,`Singleness, elasticity and integrity`,`Singleness, elasticity і integrity`),xs(`d`,`Guld, silver och koppar`,!1,`Gold, silver and copper`,`Золото, срібло і мідь`)],explanation:`BIS bedömer att stablecoins uppfyller kraven i otillräcklig grad för att bära penningsystemet.`,explanationEn:`The BIS judges that stablecoins meet the requirements too weakly to carry the monetary system.`,explanationUk:`BIS вважає, що stablecoin виконують вимоги надто слабко, щоб нести грошову систему.`},{id:`mf7-q3`,prompt:`Vad fokuserar ESMA:s nya tillsynsprioritering från 2027 på först?`,promptEn:`What does ESMA's new supervisory priority from 2027 focus on first?`,promptUk:`На чому спершу зосереджений новий наглядовий пріоритет ESMA з 2027 року?`,options:[xs(`a`,`Hur företagen använder AI och tokenisering`,!0,`How firms use AI and tokenisation`,`Як фірми використовують ШІ і токенізацію`),xs(`b`,`Sedlar och mynt`,!1,`Notes and coins`,`Банкноти і монети`),xs(`c`,`Fastighetspriser`,!1,`Property prices`,`Ціни на нерухомість`),xs(`d`,`Guldreserver`,!1,`Gold reserves`,`Золоті резерви`)],explanation:`ESMA vill att tillsynen har kunskap och kapacitet för nya tekniker.`,explanationEn:`ESMA wants supervision to have knowledge and capacity for new techniques.`,explanationUk:`ESMA хоче, щоб нагляд мав знання і спроможність для нових технік.`},{id:`mf7-q4`,prompt:`Vad är den röda tråden i kursen?`,promptEn:`What is the thread through the course?`,promptUk:`Яка червона нитка курсу?`,options:[xs(`a`,`Guld som enda säkra tillgång`,!1,`Gold as the only safe asset`,`Золото як єдиний безпечний актив`),xs(`b`,`Ledgern, en betrodd bok över vem som äger vad`,!0,`The ledger, a trusted book of who owns what`,`Книга, довірений запис того, хто чим володіє`),xs(`c`,`Att robotar ersätter människor`,!1,`That robots replace people`,`Що роботи замінюють людей`),xs(`d`,`Att allt blir kontantlöst`,!1,`That everything becomes cashless`,`Що все стає безготівковим`)],explanation:`Tråden går från tempelherrarnas konton och VOC:s bok till delade och digitala ledgers.`,explanationEn:`The thread runs from the Templars' accounts and the VOC's book to shared and digital ledgers.`,explanationUk:`Нитка йде від рахунків тамплієрів і книги VOC до спільних і цифрових книг.`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-06-sjalvforvar-kall-planbok`,labelSv:`Föregående: Självförvar`,labelEn:`Previous: Self-custody`}]}]";
const bankCourse = "{courseId:`bankernas-historia`,order:1.5,status:`available`,titleKey:`school.course.bankHistoria.title`,summaryKey:`school.course.bankHistoria.summary`,titleSv:`Bankernas historia`,titleEn:`The history of banking`,summarySv:`Riksbanken 1668, Bank of England 1694, familjen Rothschild och 1800-talets banker, delreservsystemet, Federal Reserve 1913 och IMF från Bretton Woods 1944 – och hur det hänger ihop i dag.`,summaryEn:`The Riksbank 1668, the Bank of England 1694, the Rothschild family and 19th-century banking, fractional reserve banking, the Federal Reserve 1913 and the IMF from Bretton Woods 1944 – and how it connects today.`,topicsSv:[`Centralbanker`,`Rothschild`,`Delreserv`,`Fed`,`IMF`,`Quiz`],topicsEn:[`Central banks`,`Rothschild`,`Fractional reserve`,`Fed`,`IMF`,`Quiz`],modules:bankMods,plannedLessons:8,coverImage:`/school/courses/bankernas-historia.jpg`}";
const mfCourse = "{courseId:`marknadens-framtid`,order:1.6,status:`available`,titleKey:`school.course.marknadensFramtid.title`,summaryKey:`school.course.marknadensFramtid.summary`,titleSv:`Marknadens framtid – Robotåldern`,titleEn:`The future of markets – The robot age`,summarySv:`Från tempelriddarnas och VOC:s böcker till den delade ledgern: algoritmer och AI, krypto, e-kronan och den digitala euron, ICO, självförvar och institutionernas egna planer.`,summaryEn:`From the books of the Templars and the VOC to the shared ledger: algorithms and AI, crypto, the e-krona and the digital euro, ICOs, self-custody and the institutions' own plans.`,topicsSv:[`Ledger`,`Algoritmer`,`AI`,`Krypto`,`CBDC`,`ICO`,`Självförvar`,`Quiz`],topicsEn:[`Ledger`,`Algorithms`,`AI`,`Crypto`,`CBDC`,`ICO`,`Self-custody`,`Quiz`],modules:mfMods,plannedLessons:7,coverImage:`/school/courses/marknadens-framtid.jpg`}";

const MOD_ANCHOR = ",Ms=[{courseId:`basics-sprak`";
const CAT_ANCHOR = "modules:Es,plannedLessons:5,coverImage:`/school/courses/historia.jpg`},{courseId:`ico`";
const ALIAS_FROM = 'guld:`historia`,"europa-syd":`europa-syd`';
const ALIAS_TO = 'guld:`historia`,"bankernas-historia":`bankernas-historia`,bankhistoria:`bankernas-historia`,"bank-history":`bankernas-historia`,"marknadens-framtid":`marknadens-framtid`,robotaldern:`marknadens-framtid`,"future-markets":`marknadens-framtid`,"europa-syd":`europa-syd`';

function count(hay, needle) {
  return hay.split(needle).length - 1;
}

function once(label, from, to) {
  const n = count(s, from);
  if (n !== 1) throw new Error(`${label}: expected 1 occurrence, found ${n}`);
  s = s.replace(from, to);
  console.log("ok", label);
}

const already =
  s.includes("courseId:`bankernas-historia`") &&
  s.includes("courseId:`marknadens-framtid`") &&
  s.includes(",bankMods=") &&
  s.includes(",mfMods=") &&
  s.includes(ALIAS_TO);

if (already) {
  console.log("skip courses");
} else {
  if (
    s.includes("courseId:`bankernas-historia`") ||
    s.includes("courseId:`marknadens-framtid`") ||
    s.includes(",bankMods=") ||
    s.includes(",mfMods=") ||
    s.includes('"bankernas-historia":`bankernas-historia`')
  ) {
    throw new Error("partial course patch");
  }
  once("modules", MOD_ANCHOR, `,bankMods=${bankModules},mfMods=${mfModules}${MOD_ANCHOR}`);
  once(
    "catalog",
    CAT_ANCHOR,
    `modules:Es,plannedLessons:5,coverImage:\`/school/courses/historia.jpg\`},${bankCourse},${mfCourse},{courseId:\`ico\``,
  );
  once("alias", ALIAS_FROM, ALIAS_TO);
}

const bankIds = [
  "bank-01-riksbanken-1668",
  "bank-02-bank-of-england-1694",
  "bank-03-rothschild-1800-talet",
  "bank-04-rothschild-efter-1800-talet",
  "bank-05-delreservsystemet",
  "bank-06-federal-reserve-1913",
  "bank-07-bretton-woods-imf",
  "bank-08-sa-hanger-det-ihop",
];
const mfIds = [
  "mf-01-fran-bocker-till-ledger",
  "mf-02-algoritmer-och-ai",
  "mf-03-krypto",
  "mf-04-cbdc",
  "mf-05-ico-och-tokens",
  "mf-06-sjalvforvar-kall-planbok",
  "mf-07-framtiden-enligt-kallorna",
];

const checks = [
  ["bank course once", count(s, "courseId:`bankernas-historia`") === 1],
  ["future course once", count(s, "courseId:`marknadens-framtid`") === 1],
  ["bank modules spliced", s.includes(`,bankMods=${bankModules},`)],
  ["future modules spliced", s.includes(`,mfMods=${mfModules},`)],
  ["bank cover", s.includes("coverImage:`/school/courses/bankernas-historia.jpg`")],
  ["future cover", s.includes("coverImage:`/school/courses/marknadens-framtid.jpg`")],
  ["alias", s.includes(ALIAS_TO) && count(s, ALIAS_TO) === 1],
  ["historia still before banks", s.indexOf("courseId:`historia`") < s.indexOf("courseId:`bankernas-historia`")],
  ["banks before future", s.indexOf("courseId:`bankernas-historia`") < s.indexOf("courseId:`marknadens-framtid`")],
  ["future before ico", s.indexOf("courseId:`marknadens-framtid`") < s.indexOf("courseId:`ico`")],
  ...bankIds.map((id) => [`module ${id}`, count(s, `moduleId:\`${id}\``) === 1]),
  ...mfIds.map((id) => [`module ${id}`, count(s, `moduleId:\`${id}\``) === 1]),
  ["basics clip still gone", s.includes("var In={};") && !s.includes("basics-01-samma-sprak.mp4")],
  ["compound sv clip", s.includes("youtubeUrlSv:`https://www.youtube.com/watch?v=MvNGY5UzdF4`")],
  ["leverage sv clip", s.includes("youtubeUrlSv:`https://www.youtube.com/watch?v=oUAhA_BXsNE`")],
  ["ted-ed kept", s.includes("https://www.youtube.com/watch?v=p7HKvqRI_Bo")],
  ["om-modellen kept", s.includes("/om-modellen")],
  ["nvda-rider kept", s.includes("/traderider/spel/#trade-rider")],
  ["archived balans kept", s.includes("archived-record/balans")],
  ["archived shein kept", s.includes("archived-record/shein")],
  ["light theme hook kept", s.includes("data-theme")],
  ["bank closer sv", count(s, "Historien slutar inte här.") === 1 && s.includes("sammanställt och avidentifierat")],
  ["bank closer en", count(s, "The story does not end here.") === 1 && s.includes("compiled and anonymised")],
  ["bank closer no uk", !s.includes("Історія на цьому") && !s.includes("зібрано й знеособлено")],
];

const failed = checks.filter(([, ok]) => !ok);
if (failed.length) throw new Error(`post-checks failed: ${failed.map(([name]) => name).join(", ")}`);

fs.writeFileSync(bundlePath, s);
console.log("patched", bundlePath.pathname, "bytes", s.length);
